/* Views B: Assessments, Quotes, Invoices, Projects, Tasks, Team */
(function(){

/* ===================== ASSESSMENTS (IES) ===================== */
Views.assess = id => {
  const order = DB.clients.filter(c=>c.status!=='Lost / archived').sort((a,b)=>{ const ha=DB.assessments.some(x=>x.clientId===a.id)?0:1, hb=DB.assessments.some(x=>x.clientId===b.id)?0:1; return ha-hb || a.ies-b.ies; });
  const c = get.client(id) || get.client((DB.assessments[0]||{}).clientId) || order[0];
  if(!c) return {html:`<div class="page">${pageHead('Assessments & Solution Architecture','BEMO-SOLUTIONS Evolution System™ — move every client from discovery to long-term partnership.')}${card(null, empty('compass','No clients to assess yet','Assessments follow discovery. Add a client first.',`<button class="btn pri sm" data-a="newClient">${ic('plus',13)}Add client</button>`))}</div>`, crumbs:[['Assessments']], title:'Assessments'};
  const a = DB.assessments.find(x=>x.clientId===c.id);
  const phaseCounts = IES.map(s=>DB.clients.filter(x=>x.ies===s.n && x.status!=='Lost / archived').length);
  const html = `<div class="page full">${pageHead('Assessments & Solution Architecture', 'BEMO-SOLUTIONS Evolution System™ — move every client from discovery to long-term partnership.', `<button class="btn" data-a="go" data-to="discovery">${ic('phone-call',14)}Discovery</button>`)}
    <div class="stepper" style="margin-bottom:16px">${IES.map((s,i)=>`<div class="step"><div class="n">0${s.n}</div><div class="t">${s.name}</div><div class="s">${phaseCounts[i]} client${phaseCounts[i]===1?'':'s'}</div></div>`).join('')}</div>
    <div class="split"><div class="sublist">${order.map(x=>{ const has = DB.assessments.find(y=>y.clientId===x.id); return `<div class="li ${x.id===c.id?'on':''}" data-go="assess-${x.id}">${coIc(x)}<div class="grow"><div class="t">${esc(x.name)}</div><div class="s">Phase ${x.ies} · ${IES[x.ies-1].name}${has?' · '+has.id:''}</div></div>${has?badge(has.status):'<span class="muted xs">—</span>'}</div>`; }).join('')}</div>
    <div class="tabpane">${assessWorkspace(c, a)}</div></div></div>`;
  return {html, crumbs:[['Assessments','assess'],[c.name]], title:'Assessments'};
};
function listCard(title, items, icon, tone){ return card(title, items && items.length ? `<ul class="bul">${items.map(x=>`<li>${ic(icon,14,tone||'muted')}<span>${esc(x)}</span></li>`).join('')}</ul>` : '<p class="muted small">Not captured yet.</p>'); }
function assessWorkspace(c, a){
  const ph = IES[c.ies-1];
  const stepper = `<div class="stepper">${IES.map(s=>`<div class="step ${s.n<c.ies?'done':s.n===c.ies?'cur':''}" data-a="setPhase" data-client="${c.id}" data-n="${s.n}" data-tip="${esc(s.desc)}"><div class="n">${s.n<c.ies?'✓ ':''}0${s.n}</div><div class="t">${s.name}</div></div>`).join('')}</div>`;
  const header = `<div class="card"><div class="card-b col gap-12"><div class="row between wrap"><div class="row" style="gap:12px">${coIc(c,'lg')}<div><a href="#client-${c.id}" class="strong" style="font-size:15px">${esc(c.name)}</a><div class="muted small">${esc(c.industry)} · ${esc(c.size)} staff · ${badge(c.status)}</div></div></div>${a?`<div class="row">${badge(a.status)}<span class="muted small">Updated ${fmtD(a.updated)} by ${esc(uname(a.owner))}</span></div>`:''}</div>${stepper}<div class="callout cyan">${ic('flag',15)}<span><b>Phase ${ph.n} · ${ph.name}</b> — ${esc(ph.desc)}. Deliverables: ${ph.del.map(esc).join(' · ')}</span></div></div></div>`;
  if(!a) return `<div class="col gap-16">${header}${card(null, empty('compass','No assessment for this client yet','Start from the IES template. Discovery findings are copied in automatically.',`<button class="btn pri" data-a="startAssessment" data-client="${c.id}">${ic('plus',14)}Start assessment</button>`))}</div>`;
  const oppM = {High:3, Medium:2, Low:1};
  return `<div class="col gap-16">${header}
    <div class="grid g-21">
      ${card('Business overview', `<p style="line-height:1.6">${esc(a.overview)}</p><div class="kv2 mt-16" style="grid-template-columns:repeat(3,1fr)"><div><div class="k">Estimated complexity</div><div class="v">${badge(a.complexity)}</div></div><div><div class="k">Systems in scope</div><div class="v num">${a.systems.length}</div></div><div><div class="k">Opportunities</div><div class="v num">${a.opps.length}</div></div></div>`, {act:`<button class="btn ghost xs" data-a="editAssess" data-id="${a.id}">${ic('pen-line',12)}Edit</button>`})}
      ${card('AI readiness', `<div class="col" style="align-items:center">${gauge(a.readiness)}</div><ul class="bul mt-8">${a.ai.map(x=>`<li>${ic('sparkles',13,'muted')}<span>${esc(x)}</span></li>`).join('')}</ul>`)}
    </div>
    <div class="grid g3">${listCard('Existing systems', a.systems, 'box')}${listCard('Current workflows', a.workflows, 'git-commit-horizontal')}${listCard('Pain points', a.pains, 'frown', 'warn')}</div>
    <div class="grid g2">
      ${listCard('Technical requirements', a.requirements, 'check-circle-2', 'up')}
      ${card('Automation opportunities', `<div class="tw"><table class="tbl"><thead><tr><th>Opportunity</th><th>Impact</th><th>Effort</th><th>Priority</th></tr></thead><tbody>${a.opps.slice().sort((x,y)=>(oppM[y.impact]*2-oppM[y.effort])-(oppM[x.impact]*2-oppM[x.effort])).map(o=>{ const s = oppM[o.impact]*2-oppM[o.effort]; return `<tr><td class="wrap">${esc(o.t)}</td><td>${badge(o.impact, o.impact==='High'?'green':'amber')}</td><td>${badge(o.effort, o.effort==='Low'?'green':o.effort==='Medium'?'amber':'red')}</td><td>${s>=5?'<span class="b cyan nodot">Quick win</span>':s>=3?'<span class="b blue nodot">Plan</span>':'<span class="b gray nodot">Later</span>'}</td></tr>`; }).join('')}</tbody></table></div>`, {flush:true})}
    </div>
    <div class="grid g3">${listCard('Risks', a.risks, 'alert-triangle', 'warn')}${listCard('Dependencies', a.deps, 'link')}${listCard('Security considerations', a.security, 'shield')}</div>
    <div class="grid g2">
      ${card('Recommended solution', `<p style="line-height:1.6">${esc(a.solution)}</p>`, {hint:'Owner: '+esc((get.user(a.owner)||{name:'—'}).name)})}
      ${listCard('Expected outcomes', a.outcomes, 'target', 'up')}
    </div>
    ${card(`${ic('network',15)} Solution architecture`, archSvg(a), {flush:true, hint:'Drag nodes to rearrange', act:`<button class="btn sm" data-a="addNode" data-id="${a.id}">${ic('plus',13)}Add system</button><button class="btn ghost sm" data-a="toggleFlow">${ic('play',13)}${UI.flow?'Stop':'Animate'} data flow</button>`})}
  </div>`;
}
const NODE_IC = {Email:'mail',Orchestration:'workflow','Sync engine':'workflow',Extraction:'sparkles',LLM:'sparkles','AI service':'sparkles',Database:'database','Sync log':'database','Web app':'app-window',API:'plug',Notifications:'bell',Messaging:'message-circle',BI:'bar-chart-3',Booking:'globe',CRM:'users',ERP:'server',Policies:'folder',Pipeline:'git-merge',SSO:'key-round',Audit:'clipboard-check',Website:'globe','Client portal':'app-window'};
function archSvg(a){
  const NW=152, NH=54; const N = id => a.arch.nodes.find(n=>n.id===id);
  const edge = ([f,t,l],i) => { const A1=N(f), B=N(t); if(!A1||!B) return ''; const p = edgePath(A1,B,NW,NH); return `<path class="edge ${UI.flow?'flow':''}" data-e="${i}" data-f="${f}" data-t="${t}" d="${p.d}" marker-end="url(#arr)"/>${l?`<text class="el" data-el="${i}" x="${p.mx}" y="${p.my-5}" text-anchor="middle">${esc(l)}</text>`:''}`; };
  return `<svg class="arch" id="arch" data-id="${a.id}" viewBox="0 0 880 420" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Solution architecture diagram"><defs><marker id="arr" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10 z" style="fill:var(--fg-4)"/></marker></defs>
    <g id="edges">${a.arch.edges.map(edge).join('')}</g>
    ${a.arch.nodes.map(n=>`<g class="node" data-node="${n.id}" transform="translate(${n.x},${n.y})"><rect width="${NW}" height="${NH}" rx="10"/><g transform="translate(12,15)" style="color:${/AI|LLM|Extraction/.test(n.type+n.label)?'var(--c6)':/n8n|Orchestr|Sync engine|Pipeline/.test(n.type+n.label)?'var(--accent)':'var(--fg-3)'}">${ic(NODE_IC[n.type]||'box',22)}</g><text x="44" y="24">${esc(n.label.length>16?n.label.slice(0,15)+'…':n.label)}</text><text class="nt" x="44" y="40">${esc(n.type)}</text></g>`).join('')}
  </svg>`;
}
function edgePath(A1,B,NW,NH){
  const ax=A1.x+NW/2, ay=A1.y+NH/2, bx=B.x+NW/2, by=B.y+NH/2; const dx=bx-ax, dy=by-ay;
  let sx,sy,tx,ty, horiz = Math.abs(dx) > Math.abs(dy)*1.2;
  if(horiz){ sx = ax + Math.sign(dx)*NW/2; sy=ay; tx = bx - Math.sign(dx)*NW/2; ty=by; const k=(tx-sx)/2; return {d:`M${sx} ${sy} C${sx+k} ${sy}, ${tx-k} ${ty}, ${tx} ${ty}`, mx:(sx+tx)/2, my:(sy+ty)/2}; }
  sx=ax; sy=ay+Math.sign(dy)*NH/2; tx=bx; ty=by-Math.sign(dy)*NH/2; const k=(ty-sy)/2; return {d:`M${sx} ${sy} C${sx} ${sy+k}, ${tx} ${ty-k}, ${tx} ${ty}`, mx:(sx+tx)/2+30, my:(sy+ty)/2};
}
function bindArch(){
  const svg = document.getElementById('arch'); if(!svg) return; const a = DB.assessments.find(x=>x.id===svg.dataset.id);
  let drag=null;
  const pt = e => { const p = svg.createSVGPoint(); p.x=e.clientX; p.y=e.clientY; return p.matrixTransform(svg.getScreenCTM().inverse()); };
  svg.addEventListener('pointerdown', e=>{ const g = e.target.closest('.node'); if(!g) return; const n = a.arch.nodes.find(x=>x.id===g.dataset.node); const p = pt(e); drag = {n, g, ox:p.x-n.x, oy:p.y-n.y}; g.setPointerCapture(e.pointerId); e.preventDefault(); });
  svg.addEventListener('pointermove', e=>{ if(!drag) return; const p=pt(e); drag.n.x=Math.max(0,Math.min(880-152,Math.round(p.x-drag.ox))); drag.n.y=Math.max(0,Math.min(420-54,Math.round(p.y-drag.oy))); drag.g.setAttribute('transform',`translate(${drag.n.x},${drag.n.y})`);
    a.arch.edges.forEach(([f,t],i)=>{ if(f!==drag.n.id && t!==drag.n.id) return; const pa=edgePath(a.arch.nodes.find(n=>n.id===f), a.arch.nodes.find(n=>n.id===t),152,54); const el=svg.querySelector(`[data-e="${i}"]`); el && el.setAttribute('d',pa.d); const lb=svg.querySelector(`[data-el="${i}"]`); if(lb){ lb.setAttribute('x',pa.mx); lb.setAttribute('y',pa.my-5); } }); });
  const end = ()=>{ if(drag){ drag=null; save(); } };
  svg.addEventListener('pointerup', end); svg.addEventListener('pointercancel', end);
}
A.toggleFlow = () => { UI.flow = !UI.flow; rerender(); };
A.setPhase = d => { const c=get.client(d.client); const n=+d.n; if(n===c.ies) return; confirmBox({title:`Move to ${IES[n-1].name}?`, text:`${esc(c.name)} will move from phase ${c.ies} (${IES[c.ies-1].name}) to phase ${n} (${IES[n-1].name}). This is recorded in the activity log.`, ok:'Move phase', onOk:()=>{ c.ies=n; log(`Moved to IES phase ${n} · ${IES[n-1].name}`, c.id, 'assess-'+c.id, 'assessment'); commit('Phase updated'); }}); };
A.startAssessment = d => { const c=get.client(d.client); const disc=DB.discoveries.filter(x=>x.clientId===c.id);
  const a = {id:nextId('A-',DB.assessments), clientId:c.id, status:'In progress', owner:DB.me, updated:TODAY, complexity:'Medium', readiness:50, overview:c.notes||'', systems:uniq(disc.flatMap(x=>x.systems)), workflows:[], pains:[], requirements:uniq(disc.flatMap(x=>x.confirmed)), ai:[], opps:[], risks:uniq(disc.flatMap(x=>x.risks)), deps:[], security:['POPIA compliance review'], solution:'To be defined.', outcomes:[], arch:{nodes:[{id:'n1',label:'Client systems',type:'API',x:40,y:170},{id:'n2',label:'n8n',type:'Orchestration',x:330,y:170},{id:'n3',label:'Supabase',type:'Database',x:620,y:170}],edges:[['n1','n2',''],['n2','n3','']]}};
  DB.assessments.push(a); if(c.ies<2) c.ies=2; if(STATUS.client.indexOf(c.status)<STATUS.client.indexOf('Assessment in progress')) c.status='Assessment in progress'; log('Assessment started', c.id, 'assess-'+c.id, 'assessment'); save(); go('assess-'+c.id); toast('Assessment created from discovery findings'); };
A.addNode = d => modal({title:'Add system to architecture', size:'sm', body:`<div class="col gap-12">${field('System name',`<input class="inp" id="nn-label" placeholder="e.g. Client portal">`)}${field('Type',`<select class="sel" id="nn-type">${opts(['Web app','API','Database','Orchestration','AI service','Email','Messaging','BI','CRM','ERP','Website','Client portal'],'API')}</select>`)}${field('Connect from',`<select class="sel" id="nn-from">${opts(DB.assessments.find(x=>x.id===d.id).arch.nodes.map(n=>[n.id,n.label]),'', {blank:'No connection'})}</select>`)}${field('Connection label',`<input class="inp" id="nn-edge" placeholder="e.g. sync orders">`)}</div>`, foot:`<button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn pri" data-a="saveNode" data-id="${d.id}">Add</button>`});
A.saveNode = d => { if(!requireFields([['nn-label','System name']])) return; const a=DB.assessments.find(x=>x.id===d.id); const id='n'+(a.arch.nodes.length+1)+Date.now()%1000; a.arch.nodes.push({id, label:val('nn-label'), type:val('nn-type'), x:360, y:20}); if(val('nn-from')) a.arch.edges.push([val('nn-from'), id, val('nn-edge')]); a.updated=TODAY; closeTop(); commit('System added — drag it into place'); };
A.editAssess = d => { const a=DB.assessments.find(x=>x.id===d.id); const ta=(id,v)=>`<textarea class="ta" id="${id}">${esc(v)}</textarea>`; const lines=(id,arr)=>`<textarea class="ta" id="${id}" placeholder="One per line">${esc(arr.join('\n'))}</textarea>`;
  modal({title:'Edit assessment '+a.id, size:'lg', body:`<div class="form-grid">${field('Business overview',ta('ea-ov',a.overview),'span2')}${field('Complexity',`<select class="sel" id="ea-cx">${opts(['Low','Medium','High'],a.complexity)}</select>`)}${field('AI readiness (0–100)',`<input class="inp" type="number" min="0" max="100" id="ea-rd" value="${a.readiness}">`)}${field('Existing systems',lines('ea-sys',a.systems))}${field('Current workflows',lines('ea-wf',a.workflows))}${field('Pain points',lines('ea-pain',a.pains))}${field('Technical requirements',lines('ea-req',a.requirements))}${field('AI readiness notes',lines('ea-ai',a.ai))}${field('Automation opportunities (title | impact | effort)',`<textarea class="ta" id="ea-opp" placeholder="Invoice capture | High | Medium">${esc(a.opps.map(o=>[o.t,o.impact,o.effort].join(' | ')).join('\n'))}</textarea>`)}${field('Risks',lines('ea-risk',a.risks))}${field('Dependencies',lines('ea-dep',a.deps))}${field('Security considerations',lines('ea-sec',a.security))}${field('Expected outcomes',lines('ea-out',a.outcomes))}${field('Recommended solution',ta('ea-sol',a.solution),'span2')}${field('Status',`<select class="sel" id="ea-st">${opts(['In progress','Completed'],a.status)}</select>`)}${field('Owner',`<select class="sel" id="ea-own">${userOpts(a.owner)}</select>`)}</div>`, foot:`<button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn pri" data-a="saveAssess" data-id="${a.id}">Save</button>`}); };
A.saveAssess = d => { const a=DB.assessments.find(x=>x.id===d.id); const L=id=>val(id).split('\n').map(s=>s.trim()).filter(Boolean); const lv = v => /^h/i.test(v)?'High':/^l/i.test(v)?'Low':'Medium';
  Object.assign(a,{overview:val('ea-ov'), complexity:val('ea-cx'), readiness:Math.max(0,Math.min(100,+val('ea-rd')||0)), systems:L('ea-sys'), workflows:L('ea-wf'), pains:L('ea-pain'), requirements:L('ea-req'), ai:L('ea-ai'), opps:L('ea-opp').map(l=>{ const [t,i,e]=l.split('|').map(s=>(s||'').trim()); return {t, impact:lv(i||'Medium'), effort:lv(e||'Medium')}; }), risks:L('ea-risk'), deps:L('ea-dep'), security:L('ea-sec'), solution:val('ea-sol'), outcomes:L('ea-out'), status:val('ea-st'), owner:val('ea-own'), updated:TODAY}); closeTop(); commit('Assessment saved'); };
const _assess = Views.assess; Views.assess = id => { const r=_assess(id); after(bindArch); return r; };

/* ===================== QUOTES ===================== */
Views.quotes = () => {
  const f = UI.f.quotes || ''; const q = (UI.q.quotes||'').toLowerCase();
  const all = DB.quotes;
  const rows = all.filter(x => (!f || (f==='awaiting' ? ['Sent','Viewed'].includes(x.status) : x.status===f)) && (!q || [x.id,x.title,get.client(x.clientId).name].join(' ').toLowerCase().includes(q)));
  const decided = all.filter(x=>['Accepted','Rejected','Expired'].includes(x.status));
  const kp = [
    {l:'Total quoted (ex VAT)', v:fmtRk(sum(all,x=>calc.quote(x).sub)), d:`${all.length} quotes`},
    {l:'Accepted value', v:fmtRk(sum(all.filter(x=>x.status==='Accepted'),x=>calc.quote(x).sub)), d:`${all.filter(x=>x.status==='Accepted').length} accepted`, tone:'up'},
    {l:'Awaiting response', v:fmtR(sum(all.filter(x=>['Sent','Viewed'].includes(x.status)),x=>calc.quote(x).sub)), d:`${all.filter(x=>['Sent','Viewed'].includes(x.status)).length} quotes`, tone:'warn'},
    {l:'In preparation', v:all.filter(x=>['Draft','Internal review'].includes(x.status)).length, d:'Draft & internal review'},
    {l:'Acceptance rate', v:pct(all.filter(x=>x.status==='Accepted').length, decided.length)+'%', d:'Of decided quotes'}
  ];
  const chips = [['','All'],['awaiting','Awaiting response']].concat(STATUS.quote.map(s=>[s,s]));
  const html = `<div class="page full">${pageHead('Quotes', 'Proposals and commercial scope. An accepted quote is a commitment — it is not a payment.', `<button class="btn pri" data-a="newQuote">${ic('plus',14)}New quote</button>`)}
    <div class="kpis" style="grid-template-columns:repeat(5,minmax(0,1fr));margin-bottom:16px">${kp.map(kpiCell).join('')}</div>
    <div class="toolbar">${searchBox('quotes','Search quotes…')}${chips.map(([v,l])=>`<button class="fchip ${f===v?'on':''}" data-a="fchip" data-key="quotes" data-v="${v}">${l}<span class="ct">${v===''?all.length:v==='awaiting'?all.filter(x=>['Sent','Viewed'].includes(x.status)).length:all.filter(x=>x.status===v).length}</span></button>`).join('')}</div>
    ${card(null, table({key:'quotes', rows, go:x=>'quote-'+x.id, cols:[
      {k:'id',l:'Quote',r:x=>`<span class="mono">${x.id}</span>`},
      {k:'title',l:'Title',r:x=>`<div class="cell-t">${esc(x.title)}</div><div class="cell-s">${x.projectId?'Project '+x.projectId:'Opportunity'}</div>`},
      {k:'clientId',l:'Client',r:x=>esc(get.client(x.clientId).name),sv:x=>get.client(x.clientId).name},
      {k:'type',l:'Project type',r:x=>x.type?catTag(x.type):'<span class="muted">—</span>'},
      {k:'version',l:'Ver.',r:x=>'v'+x.version},
      {k:'owner',l:'Owner',r:x=>who(x.owner),sv:x=>uname(x.owner)},
      {k:'sent',l:'Sent',r:x=>x.sent?fmtD(x.sent):'<span class="muted">Not sent</span>',sv:x=>x.sent||''},
      {k:'valid',l:'Valid until',r:x=>{ if(!x.sent) return '<span class="muted">—</span>'; const v=addDays(x.sent,x.validDays); return `<span class="${v<TODAY&&!['Accepted','Rejected'].includes(x.status)?'down':''}">${fmtD(v)}</span>`; }},
      {k:'sub',l:'Ex VAT',cls:'r',r:x=>`<span class="num">${fmtR(calc.quote(x).sub)}</span>`,sv:x=>calc.quote(x).sub},
      {k:'tot',l:'Total incl. VAT',cls:'r',r:x=>`<span class="num strong">${fmtR(calc.quote(x).total)}</span>`,sv:x=>calc.quote(x).total},
      {k:'status',l:'Status',r:x=>badge(x.status),sv:x=>STATUS.quote.indexOf(x.status)}
    ]}), {flush:true})}</div>`;
  return {html, crumbs:[['Quotes']], title:'Quotes'};
};
function coBlock(){ const C = DB.settings.company; return `<b style="font-size:15px">${esc(C.name)}</b><div class="dmuted" style="font-size:11px">${[C.tagline, [C.reg?'Reg. '+C.reg:'', C.vatNo?'VAT '+C.vatNo:''].filter(Boolean).join(' · '), C.address, [C.email, C.phone].filter(Boolean).join(' · ')].filter(Boolean).map(esc).join('<br>')}</div>`; }
window.coBlock = coBlock;
function quoteDoc(q){
  if(window.brandQuoteDoc) return window.brandQuoteDoc(q);
  const c = get.client(q.clientId); const t = calc.quote(q);
  return `<div class="doc"><div class="row between" style="align-items:flex-start"><div class="dlogo"><span class="logo">${LOGO(18)}</span><div>${coBlock()}</div></div><div style="text-align:right"><h2>Quotation</h2><div class="dmuted">${q.id} · Version ${q.version}</div>${q.status==='Accepted'?'<div class="stamp" style="margin-top:6px">Accepted</div>':''}</div></div>
    <div class="row between" style="margin-top:26px;align-items:flex-start;gap:20px;flex-wrap:wrap"><div><div class="dmuted" style="font-size:10.5px;text-transform:uppercase;letter-spacing:.06em">Prepared for</div><b>${esc(c.name)}</b><div>${esc(c.contact)}, ${esc(c.title)}</div><div class="dmuted">${esc(c.email)}</div></div><div style="text-align:right"><div><span class="dmuted">Date</span> ${fmtD(q.sent||q.created)}</div><div><span class="dmuted">Valid for</span> ${q.validDays} days</div><div><span class="dmuted">Project type</span> ${esc(q.type)}</div></div></div>
    <h3 style="font-size:15px;margin-top:24px">${esc(q.title)}</h3>${q.description?`<p style="margin-top:6px" class="dmuted">${esc(q.description)}</p>`:''}
    ${q.scope&&q.scope.length?`<div style="margin-top:12px"><b style="font-size:11px;text-transform:uppercase;letter-spacing:.06em">Scope</b><ul style="margin:6px 0 0;padding-left:18px">${q.scope.map(s=>`<li>${esc(s)}</li>`).join('')}</ul></div>`:''}
    <table><thead><tr><th style="width:52%">Description</th><th style="text-align:right">Qty</th><th style="text-align:right">Unit price</th><th style="text-align:right">Amount</th></tr></thead><tbody>${q.items.map(i=>`<tr><td>${esc(i.desc)}</td><td style="text-align:right">${i.qty}${i.unit&&i.unit!=='item'?' '+esc(i.unit):''}</td><td style="text-align:right">${fmtR(i.price,true)}</td><td style="text-align:right">${fmtR(i.qty*i.price,true)}</td></tr>`).join('')}</tbody></table>
    <div class="tot"><div><span>Subtotal</span><span>${fmtR(t.sub,true)}</span></div><div><span>VAT (${Math.round(q.vat*100)}%)</span><span>${fmtR(t.vat,true)}</span></div><div class="gt"><span>Total</span><span>${fmtR(t.total,true)}</span></div></div>
    <div style="margin-top:26px;font-size:11px" class="dmuted"><b style="color:#141c22">Terms.</b> ${DB.settings.workflow.depositPct}% deposit on acceptance; balance on agreed milestones. Work starts once the deposit has cleared. Prices in South African Rand. AI components are delivered with human-approval controls as described in the scope.</div>
    ${DB.settings.company.bank?`<div style="margin-top:10px;font-size:11px" class="dmuted">Banking: ${esc(DB.settings.company.bank)} · Ref ${q.id}</div>`:""}</div>`;
}
window.quoteDoc = quoteDoc;
Views.quote = id => {
  const q = get.quote(id); if(!q) return {html:`<div class="page">${empty('search-x','Quote not found','')}</div>`};
  const c = get.client(q.clientId); const t = calc.quote(q); const inv = DB.invoices.filter(i=>i.quoteId===q.id);
  const valid = q.sent ? addDays(q.sent, q.validDays) : null;
  const acts = {
    'Draft':(DB.settings.workflow.quoteApproval?[['submitReview','Submit for internal review','send-to-back','pri']]:[['sendQuote','Send to client','send','pri']]).concat([['editQuote','Edit quote','pen-line']]),
    'Internal review':[['sendQuote','Approve & send to client','send','pri'],['editQuote','Edit quote','pen-line'],['backToDraft','Return to draft','undo-2']],
    'Sent':[['acceptQuote','Mark as accepted','badge-check','acc'],['markViewed','Mark as viewed','eye'],['rejectQuote','Mark as rejected','x-circle','danger'],['sendQuote','Resend','send']],
    'Viewed':[['acceptQuote','Mark as accepted','badge-check','acc'],['rejectQuote','Mark as rejected','x-circle','danger'],['sendQuote','Resend','send']],
    'Accepted':[],'Rejected':[],'Expired':[]
  }[q.status];
  const next = q.status==='Accepted' ? `<div class="callout cyan">${ic('info',15)}<span>Accepted on ${fmtD(q.accepted)}. ${inv.length?`Invoiced: ${inv.map(i=>`<a href="#invoices-${i.id}" class="strong">${i.id}</a> (${calc.inv(i).status})`).join(', ')}.`:'<b>No invoice has been issued yet</b> — acceptance is not payment.'}</span></div>
    <div class="col" style="gap:8px">${!inv.length?`<button class="btn acc" data-a="invoiceFromQuote" data-id="${q.id}">${ic('receipt',14)}Create deposit invoice</button>`:''}${!q.projectId?`<button class="btn" data-a="newProject" data-quote="${q.id}">${ic('folder-plus',14)}Create project from quote</button>`:`<a class="btn" href="#project-${q.projectId}">${ic('folder-kanban',14)}Open project ${q.projectId}</a>`}</div>` : q.status==='Rejected' ? `<div class="callout red">${ic('x-circle',15)}<span>Rejected ${q.rejected?'on '+fmtD(q.rejected):''}. ${esc(q.rejectReason||'')}</span></div>` : q.status==='Expired' ? `<div class="callout">${ic('hourglass',15)}<span>Expired ${valid?fmtD(valid):''}. Duplicate it to send a fresh version.</span></div>` : '';
  const html = `<div class="page full">
    <div class="dh"><div class="dh-l"><span class="co-ic lg">${ic('file-text',20)}</span><div><h1>${esc(q.title)}</h1><div class="meta"><span class="mono">${q.id}</span><span>v${q.version}</span><a href="#client-${c.id}">${esc(c.name)}</a>${badge(q.status)}</div></div></div>
      <div class="ph-act"><button class="btn sm" data-a="printQuote" data-id="${q.id}">${ic('printer',13)}Print / save PDF</button><button class="btn sm" data-a="dupQuote" data-id="${q.id}">${ic('copy',13)}Duplicate</button><button class="btn sm" data-a="newReminder" data-kind="quote" data-ref="${q.id}" data-client="${q.clientId}">${ic('alarm-clock',13)}Reminder</button>${(window.can&&can('delete_data'))?`<button class="ib sm" data-a="delQuote" data-id="${q.id}" data-tip="Delete quote" aria-label="Delete quote">${ic('trash-2',15)}</button>`:''}</div></div>
    <div class="grid" style="grid-template-columns:minmax(0,1fr) 330px;align-items:start" id="q-grid">
      <div style="background:var(--surface-2);border:1px solid var(--line);border-radius:12px;padding:24px;overflow-x:auto">${quoteDoc(q)}</div>
      <div class="stack">
        ${card('Commercial', `<dl class="kv" style="grid-template-columns:110px 1fr"><dt>Client</dt><dd><a href="#client-${c.id}">${esc(c.name)}</a></dd><dt>Opportunity</dt><dd>${q.projectId?`<a href="#project-${q.projectId}">${q.projectId}</a>`:'New opportunity'}</dd><dt>Type</dt><dd>${esc(q.type)}</dd><dt>Owner</dt><dd>${who(q.owner)}</dd><dt>Created</dt><dd>${fmtD(q.created)}</dd><dt>Sent</dt><dd>${q.sent?fmtD(q.sent):'Not sent'}</dd><dt>Valid until</dt><dd>${valid?fmtD(valid):'—'}</dd><dt>Subtotal</dt><dd class="num">${fmtR(t.sub,true)}</dd><dt>VAT ${Math.round(q.vat*100)}%</dt><dd class="num">${fmtR(t.vat,true)}</dd><dt>Total</dt><dd class="num strong">${fmtR(t.total,true)}</dd></dl>`)}
        ${card('Actions', `<div class="col" style="gap:8px">${acts.map(([a,l,i,cls])=>`<button class="btn ${cls||''}" data-a="${a}" data-id="${q.id}">${ic(i,14)}${l}</button>`).join('')}${next}</div>${q.sentBy?`<p class="muted xs mt-12">Sent by <b>${esc(uname(q.sentBy))}</b> on ${fmtD(q.sent)}${q.sentVia?' · '+esc(q.sentVia):''}.</p>`:''}<p class="muted xs mt-8">Every status change is recorded with your name automatically.</p>`)}
        ${card('Version history', `<div class="tl">${(q.history&&q.history.length?q.history:[{v:q.version,date:q.created,note:'Created'}]).slice().reverse().map(h=>`<div class="tl-i"><span class="tl-ic mono" style="font-size:10px">v${h.v}</span><div class="tl-b"><div class="t">${esc(h.note)}</div><div class="s">${fmtD(h.date)}</div></div></div>`).join('')}</div>`)}
      </div></div></div>`;
  after(()=>{ if(window.innerWidth<1100){ const g=$('#q-grid'); if(g) g.style.gridTemplateColumns='minmax(0,1fr)'; } });
  return {html, crumbs:[['Quotes','quotes'],[q.id]], title:q.id};
};
const qlog = (q, text, kind) => { log(text, q.clientId, 'quote-'+q.id, kind||'quote'); };
A.submitReview = d => { const q=get.quote(d.id); q.status='Internal review'; qlog(q, `Quote <b>${q.id}</b> submitted for internal review`); notify('review', `${q.id} needs internal review`, 'quote-'+q.id); commit('Submitted for internal review'); };
A.backToDraft = d => { const q=get.quote(d.id); q.status='Draft'; commit('Returned to draft'); };
A.sendQuote = d => { const q=get.quote(d.id); const c=get.client(q.clientId); confirmBox({title:'Send quote to client?', text:`This will record ${q.id} (${fmtR(calc.quote(q).total,true)} incl. VAT) as sent to <b>${esc(c.contact)}</b> at ${esc(c.email)}. In this demo no email is actually sent.`, ok:'Send quote', onOk:()=>{ q.status='Sent'; q.sent=TODAY; if(STATUS.client.indexOf(c.status)<STATUS.client.indexOf('Quote sent')) c.status='Quote sent'; qlog(q, `Quote <b>${q.id}</b> sent to ${esc(c.name)}`); commit('Quote sent (simulated)'); }}); };
A.markViewed = d => { const q=get.quote(d.id); q.status='Viewed'; q.viewed=TODAY; qlog(q, `Quote <b>${q.id}</b> viewed by client`); commit('Marked as viewed'); };
A.acceptQuote = d => { const q=get.quote(d.id); const c=get.client(q.clientId); confirmBox({title:'Record client acceptance?', text:`Confirm that <b>${esc(c.name)}</b> has accepted ${q.id} for ${fmtR(calc.quote(q).total,true)} incl. VAT.<br><br>This does <b>not</b> issue an invoice or record a payment. You can create the deposit invoice next.`, ok:'Record acceptance', onOk:()=>{ q.status='Accepted'; q.accepted=TODAY; (q.history=q.history||[]).push({v:q.version,date:TODAY,note:'Accepted by client'}); if(STATUS.client.indexOf(c.status)<STATUS.client.indexOf('Accepted')) c.status='Accepted'; if(c.ies<3) c.ies=3; qlog(q, `Quote <b>${q.id}</b> accepted by ${esc(c.name)}`, 'accepted'); notify('accepted', `Quote ${q.id} accepted by ${c.name}`, 'quote-'+q.id); commit('Acceptance recorded'); }}); };
A.rejectQuote = d => modal({title:'Mark quote as rejected', size:'sm', body:field('Reason (optional)',`<textarea class="ta" id="rj-reason" placeholder="e.g. Chose a cheaper off-the-shelf option"></textarea>`), foot:`<button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn danger" data-a="saveReject" data-id="${d.id}">Mark rejected</button>`});
A.saveReject = d => { const q=get.quote(d.id); q.status='Rejected'; q.rejected=TODAY; q.rejectReason=val('rj-reason'); qlog(q, `Quote <b>${q.id}</b> rejected`); closeTop(); commit('Quote marked as rejected'); };
A.dupQuote = d => { const q=get.quote(d.id); const n = JSON.parse(JSON.stringify(q)); n.id = nextId('Q-',DB.quotes); n.status='Draft'; n.version=1; n.created=TODAY; n.sent=null; n.accepted=null; n.rejected=null; n.projectId=null; n.history=[{v:1,date:TODAY,note:'Duplicated from '+q.id}]; DB.quotes.push(n); qlog(n, `Duplicated ${q.id} as <b>${n.id}</b>`); save(); go('quote-'+n.id); toast(`${n.id} created as draft`); };
A.pdfQuote = d => modal({title:'PDF preview · '+d.id, size:'xl', body:`<div class="callout" style="margin-bottom:14px">${ic('info',15)}<span>Preview of the generated PDF. Downloads are disabled in this demo; in production the PDF is stored in Documents and attached to the email.</span></div><div style="background:var(--surface-3);padding:24px;border-radius:10px;overflow-x:auto">${quoteDoc(get.quote(d.id))}</div>`, foot:`<button class="btn" data-a="closeTop">Close</button>`});
A.invoiceFromQuote = d => { const q=get.quote(d.id); const sub = Math.round(calc.quote(q).sub * (DB.settings.workflow.depositPct/100)); A.newInvoice({client:q.clientId, quote:q.id, project:q.projectId||'', desc:`${q.title} — ${DB.settings.workflow.depositPct}% deposit`, sub}); };

/* Quote editor */
function liRow(i, it){ return `<div class="li-ed" data-li="${i}"><input class="inp sm" id="qi-d-${i}" value="${esc(it.desc)}" placeholder="Line item description" data-in="qCalc"><input class="inp sm num" type="number" min="0" step="1" id="qi-q-${i}" value="${it.qty}" data-in="qCalc" aria-label="Quantity"><input class="inp sm num" type="number" min="0" step="100" id="qi-p-${i}" value="${it.price}" data-in="qCalc" aria-label="Unit price"><span class="num right small lt" id="qi-t-${i}">${fmtR(it.qty*it.price)}</span><button class="ib sm" data-a="qDelRow" data-i="${i}" aria-label="Remove line">${ic('trash-2',14)}</button></div>`; }
function quoteEditor(q){
  return `<div class="form-grid">${field('Client *',`<select class="sel" id="qe-client">${clientOpts(q.clientId,'Select client')}</select>`)}${field('Related project / opportunity',`<select class="sel" id="qe-proj">${opts(DB.projects.map(p=>[p.id,p.id+' · '+p.name]), q.projectId||'', {blank:'New opportunity'})}</select>`)}
    ${field('Quote title *',`<input class="inp" id="qe-title" value="${esc(q.title)}" placeholder="e.g. Invoice Processing Automation">`,'span2')}
    ${field('Project type',`<input class="inp" id="qe-type" list="ptype-list" value="${esc(q.type||'')}" placeholder="Type anything, e.g. Website rebuild"><datalist id="ptype-list">${STATUS.categories.map(x=>`<option value="${esc(x)}">`).join('')}</datalist>`)}${field('Validity (days)',`<input class="inp" type="number" id="qe-valid" value="${q.validDays||30}">`)}
    ${field('Description',`<textarea class="ta" id="qe-desc">${esc(q.description||'')}</textarea>`,'span2')}
    ${field('Scope (one item per line)',`<textarea class="ta" id="qe-scope">${esc((q.scope||[]).join('\n'))}</textarea>`,'span2')}</div>
    <div class="section-t">Line items</div><div class="col" style="gap:6px" id="qe-items"><div class="li-ed h"><span>Description</span><span>Qty</span><span>Unit price (R)</span><span class="right lt">Amount</span><span></span></div>${q.items.map((it,i)=>liRow(i,it)).join('')}</div>
    <button class="btn sm mt-8" data-a="qAddRow">${ic('plus',13)}Add line item</button>
    <div class="row mt-16" style="justify-content:flex-end"><div style="width:260px" class="col" id="qe-tot"></div></div>`;
}
function qTotals(){ let sub=0; $$('#qe-items [data-li]').forEach(r=>{ const i=r.dataset.li; const q=+val('qi-q-'+i)||0, p=+val('qi-p-'+i)||0; sub+=q*p; const t=$('#qi-t-'+i); if(t) t.textContent=fmtR(q*p); }); const el=$('#qe-tot'); if(el) el.innerHTML = `<div class="row between"><span class="muted">Subtotal</span><span class="num">${fmtR(sub,true)}</span></div><div class="row between"><span class="muted">VAT ${DB.settings.workflow.vat??15}%</span><span class="num">${fmtR(sub*(DB.settings.workflow.vat??15)/100,true)}</span></div><div class="row between strong" style="border-top:1px solid var(--line);padding-top:6px;font-size:14px"><span>Total</span><span class="num">${fmtR(sub*(1+(DB.settings.workflow.vat??15)/100),true)}</span></div>`; }
A.qCalc = () => qTotals();
A.qAddRow = () => { const box=$('#qe-items'); const i = Date.now()%100000; box.insertAdjacentHTML('beforeend', liRow(i,{desc:'',qty:1,price:0})); $('#qi-d-'+i).focus(); qTotals(); };
A.qDelRow = d => { const r = document.querySelector(`[data-li="${d.i}"]`); r && r.remove(); qTotals(); };
function readQuote(){ const items = $$('#qe-items [data-li]').map(r=>{ const i=r.dataset.li; return {desc:val('qi-d-'+i), qty:+val('qi-q-'+i)||0, price:+val('qi-p-'+i)||0, unit:'item'}; }).filter(x=>x.desc); return {clientId:val('qe-client'), projectId:val('qe-proj')||null, title:val('qe-title'), type:val('qe-type'), validDays:+val('qe-valid')||30, description:val('qe-desc'), scope:val('qe-scope').split('\n').map(s=>s.trim()).filter(Boolean), items}; }
A.newQuote = d => { d=d||{}; closePop(); const q = {clientId:d.client||'', title:'', type:'', items:[{desc:'',qty:1,price:0}]};
  modal({title:'New quote', size:'xl', body:quoteEditor(q), foot:`<span class="muted small grow">Saved as Draft.${DB.settings.workflow.quoteApproval?' Internal review is required before sending.':''}</span><button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn pri" data-a="saveQuote">${ic('check',14)}Save draft</button>`}); setTimeout(qTotals, 0); };
A.saveQuote = () => { if(!requireFields([['qe-client','Client'],['qe-title','Quote title']])) return; const r = readQuote(); if(!r.items.length) return toast('Add at least one line item','err');
  const q = Object.assign({id:nextId('Q-',DB.quotes), status:'Draft', version:1, created:TODAY, sent:null, owner:DB.me, vat:(DB.settings.workflow.vat??15)/100, history:[{v:1,date:TODAY,note:'Created'}]}, r);
  DB.quotes.push(q); const c=get.client(q.clientId); if(STATUS.client.indexOf(c.status)<STATUS.client.indexOf('Quote preparation')) c.status='Quote preparation'; qlog(q, `Draft quote <b>${q.id}</b> created`); closeTop(); save(); go('quote-'+q.id); toast(`${q.id} saved as draft`); };
A.editQuote = d => { const q=get.quote(d.id); modal({title:'Edit '+q.id, size:'xl', body:quoteEditor(q), foot:`<span class="muted small grow">${q.status!=='Draft'?'Saving creates version '+(q.version+1)+'.':''}</span><button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn pri" data-a="updateQuote" data-id="${q.id}">Save changes</button>`}); setTimeout(qTotals,0); };
A.updateQuote = d => { if(!requireFields([['qe-title','Quote title']])) return; const q=get.quote(d.id); const r=readQuote(); if(!r.items.length) return toast('Add at least one line item','err'); const before = calc.quote(q).sub; Object.assign(q, r); q.history=q.history||[]; if(q.status!=='Draft'){ q.version++; q.status='Draft'; } q.history.push({v:q.version, date:TODAY, note:`Edited — ${fmtR(before)} → ${fmtR(calc.quote(q).sub)}`}); qlog(q, `Quote <b>${q.id}</b> edited (v${q.version})`); closeTop(); commit('Quote updated'); };

/* ===================== INVOICES ===================== */
Views.invoices = id => {
  const f = UI.f.inv || ''; const q=(UI.q.inv||'').toLowerCase();
  const all = DB.invoices.map(i=>({i, c:calc.inv(i)}));
  const rows = all.filter(x=>(!f || x.c.status===f || (f==='Overdue' && x.c.overdue)) && (!q || [x.i.id, x.i.desc, get.client(x.i.clientId).name].join(' ').toLowerCase().includes(q))).map(x=>x.i);
  const live = all.filter(x=>!['Draft','Cancelled'].includes(x.c.status));
  const kp = [
    {l:'Invoiced (incl. VAT)', v:fmtRk(sum(live,x=>x.c.total)), d:`${live.length} issued invoices`},
    {l:'Received', v:fmtRk(sum(live,x=>x.c.received)), d:pct(sum(live,x=>x.c.received), sum(live,x=>x.c.total))+'% collected', tone:'up'},
    {l:'Outstanding', v:fmtR(sum(live,x=>x.c.outstanding)), d:`${live.filter(x=>x.c.outstanding>0).length} invoices open`, tone:'warn'},
    {l:'Overdue', v:fmtR(sum(live.filter(x=>x.c.overdue),x=>x.c.outstanding)), d:`${live.filter(x=>x.c.overdue).length} past due date`, tone:'down'},
    {l:'Drafts', v:all.filter(x=>x.c.status==='Draft').length, d:fmtR(sum(all.filter(x=>x.c.status==='Draft'),x=>x.c.total))+' not yet issued'}
  ];
  const chips = [['','All']].concat(STATUS.invoice.map(s=>[s,s]));
  const html = `<div class="page full">${pageHead('Invoices & Payments', 'Track what has been billed, what has been paid and what is outstanding.', `<button class="btn" data-a="recordPaymentPick">${ic('banknote',14)}Record payment</button><button class="btn pri" data-a="newInvoice">${ic('plus',14)}New invoice</button>`)}
    <div class="kpis" style="grid-template-columns:repeat(5,minmax(0,1fr));margin-bottom:16px">${kp.map(kpiCell).join('')}</div>
    <div class="toolbar">${searchBox('inv','Search invoices…')}${chips.map(([v,l])=>`<button class="fchip ${f===v?'on':''}" data-a="fchip" data-key="inv" data-v="${v}">${l}<span class="ct">${v===''?all.length:all.filter(x=>x.c.status===v||(v==='Overdue'&&x.c.overdue)).length}</span></button>`).join('')}</div>
    ${card(null, table({key:'inv', rows, act:i=>`data-a="openInvoice" data-id="${i.id}"`, cols:invCols()}), {flush:true})}</div>`;
  if(id && get.invoice(id)) after(()=>{ if(!STACK.length) A.openInvoice({id}); });
  return {html, crumbs:[['Invoices & Payments','invoices']].concat(id?[[id]]:[]), title:'Invoices'};
};
function invDoc(i){ if(window.brandInvoiceDoc) return window.brandInvoiceDoc(i); const c=get.client(i.clientId), t=calc.inv(i); return `<div class="doc" style="padding:28px 30px"><div class="row between" style="align-items:flex-start"><div class="dlogo"><span class="logo">${LOGO(16)}</span><div><b>${esc(DB.settings.company.name)}</b><div class="dmuted" style="font-size:11px">${DB.settings.company.vatNo?'VAT '+esc(DB.settings.company.vatNo):''}</div></div></div><div style="text-align:right"><h2 style="font-size:18px">Tax invoice</h2><div class="dmuted">${i.id}</div>${t.status==='Paid'?'<div class="stamp" style="margin-top:6px">Paid</div>':''}</div></div><div class="row between" style="margin-top:18px;flex-wrap:wrap;gap:12px"><div><div class="dmuted" style="font-size:10.5px;text-transform:uppercase">Bill to</div><b>${esc(c.name)}</b><div class="dmuted">${esc(c.location)}</div></div><div style="text-align:right"><div><span class="dmuted">Issued</span> ${fmtD(i.issued)}</div><div><span class="dmuted">Due</span> ${fmtD(i.due)}</div>${i.quoteId?`<div><span class="dmuted">Quote</span> ${i.quoteId}</div>`:''}</div></div><table><thead><tr><th>Description</th><th style="text-align:right">Amount</th></tr></thead><tbody><tr><td>${esc(i.desc)}</td><td style="text-align:right">${fmtR(t.sub,true)}</td></tr></tbody></table><div class="tot"><div><span>Subtotal</span><span>${fmtR(t.sub,true)}</span></div><div><span>VAT ${Math.round(i.vat*100)}%</span><span>${fmtR(t.vat,true)}</span></div><div class="gt"><span>Total due</span><span>${fmtR(t.total,true)}</span></div></div></div>`; }
window.invDoc = invDoc;
A.openInvoice = d => {
  drawer({size:'wide', title:()=>{ const i=get.invoice(d.id); return `${i.id} · ${esc(get.client(i.clientId).name)}`; }, badge:'', render:()=>{
    const i = get.invoice(d.id); const t = calc.inv(i); const p = i.projectId && get.project(i.projectId);
    return `<div class="col gap-16"><div class="kpis" style="grid-template-columns:repeat(3,1fr)">${kpiCell({l:'Total incl. VAT', v:fmtR(t.total,true)})}${kpiCell({l:'Received', v:fmtR(t.received,true), tone:'up'})}${kpiCell({l:'Outstanding', v:fmtR(t.outstanding,true), d:t.overdue?`${t.daysOver} days overdue`:'', tone:t.overdue?'down':''})}</div>
      <div class="row wrap">${badge(t.status)}${t.overdue&&t.status!=='Overdue'?badge('Overdue'):''}<span class="muted small">Client: <a href="#client-${i.clientId}">${esc(get.client(i.clientId).name)}</a></span>${i.quoteId?`<span class="muted small">· Quote <a href="#quote-${i.quoteId}">${i.quoteId}</a></span>`:''}${p?`<span class="muted small">· Project <a href="#project-${p.id}">${esc(p.name)}</a></span>`:''}</div>
      <div class="row wrap"><button class="btn pri sm" data-a="sendInvoice" data-id="${i.id}">${ic('send',13)}${i.sentAt?'Send again':'Send invoice'}</button><button class="btn sm" data-a="printInvoice" data-id="${i.id}">${ic('printer',13)}Print / PDF</button>${t.status==='Draft'?`<button class="btn sm" data-a="issueInvoice" data-id="${i.id}">${ic('check',13)}Mark issued (no email)</button>`:''}${t.outstanding>0?`<button class="btn acc sm" data-a="recordPayment" data-id="${i.id}">${ic('banknote',13)}Record payment</button><button class="btn sm" data-a="remindInvoice" data-id="${i.id}">${ic('bell-ring',13)}Send reminder</button>`:''}<button class="btn sm" data-a="newReminder" data-kind="invoice" data-ref="${i.id}" data-client="${i.clientId}">${ic('alarm-clock',13)}Reminder</button>${!['Cancelled','Paid'].includes(t.status)&&t.received===0?`<button class="btn sm danger" data-a="cancelInvoice" data-id="${i.id}">${ic('ban',13)}Cancel invoice</button>`:''}${(window.can&&can('delete_data'))?`<button class="btn sm danger" data-a="delInvoice" data-id="${i.id}">${ic('trash-2',13)}Delete</button>`:''}</div>${i.sentAt?`<p class="muted xs">Last emailed ${fmtD(i.sentAt)} by ${esc(uname(i.sentBy))} to ${esc(i.sentTo||'')}</p>`:''}
      ${card('Payments', i.payments.length?`<div class="tw"><table class="tbl"><thead><tr><th>Date</th><th>Method</th><th>Reference</th><th class="r">Amount</th></tr></thead><tbody>${i.payments.map((pm,pi)=>`<tr><td>${fmtD(pm.date)}</td><td>${esc(pm.method)}</td><td class="mono small">${esc(pm.ref)}</td><td class="r num">${fmtR(pm.amount,true)}${(window.can&&can('delete_data'))?` <button class="ib sm" style="width:20px;height:20px" data-a="delPayment" data-id="${i.id}" data-i="${pi}" aria-label="Delete payment">${ic('x',12)}</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('banknote','No payments recorded',''), {flush:true})}
      <div style="background:var(--surface-3);padding:16px;border-radius:10px;overflow-x:auto">${invDoc(i)}</div></div>`;
  }});
};
A.issueInvoice = d => { const i=get.invoice(d.id); i.flag=null; i.issued=TODAY; i.due=addDays(TODAY,14); log(`Issued invoice <b>${i.id}</b>`, i.clientId, 'invoices-'+i.id, 'invoice'); commit(`${i.id} issued (simulated)`); };
A.cancelInvoice = d => confirmBox({title:'Cancel invoice?', text:`${d.id} will be marked as cancelled and excluded from outstanding balances. A credit note is not generated in the demo.`, ok:'Cancel invoice', danger:true, onOk:()=>{ const i=get.invoice(d.id); i.flag='cancelled'; log(`Cancelled invoice ${i.id}`, i.clientId, 'invoices', 'invoice'); commit('Invoice cancelled'); }});
A.remindInvoice = d => { const i=get.invoice(d.id); log(`Payment reminder sent for <b>${i.id}</b>`, i.clientId, 'invoices-'+i.id, 'email'); DB.conversations.unshift({id:nextId('CV-',DB.conversations), clientId:i.clientId, channel:'email', subject:'Payment reminder — '+i.id, participants:[get.client(i.clientId).contact, me().name], assigned:DB.me, projectId:i.projectId, followUp:'Open', messages:[{from:me().name, at:nowStamp(), body:`Dear ${get.client(i.clientId).contact},\n\nThis is a friendly reminder that ${i.id} for ${fmtR(calc.inv(i).outstanding,true)} was due on ${fmtD(i.due)}. Please let us know if you need anything from us.\n\nKind regards`, attachments:[i.id+'.pdf']}]}); commit('Reminder recorded (simulated send)'); };
A.recordPayment = d => { const i=get.invoice(d.id); const t=calc.inv(i); modal({title:'Record payment · '+i.id, body:`<div class="callout" style="margin-bottom:14px">${ic('info',15)}<span>${esc(get.client(i.clientId).name)} · outstanding <b>${fmtR(t.outstanding,true)}</b> of ${fmtR(t.total,true)}</span></div><div class="form-grid">${field('Amount received (R) *',`<input class="inp num" type="number" step="0.01" min="0" id="pm-amt" value="${t.outstanding.toFixed(2)}">`)}${field('Payment date',`<input class="inp" type="date" id="pm-date" value="${TODAY}">`)}${field('Method',`<select class="sel" id="pm-method">${opts(['EFT','Debit order','Card','Cash'],'EFT')}</select>`)}${field('Bank reference',`<input class="inp" id="pm-ref" placeholder="e.g. HAG-1201">`)}</div>`, foot:`<button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn acc" data-a="savePayment" data-id="${i.id}">${ic('check',14)}Record payment</button>`}); };
A.savePayment = d => { const i=get.invoice(d.id); const t=calc.inv(i); const amt = Math.round((+val('pm-amt')||0)*100)/100; if(amt<=0) return toast('Enter an amount greater than zero','err'); if(amt>t.outstanding+0.01) return toast(`Amount exceeds outstanding balance of ${fmtR(t.outstanding,true)}`,'err');
  i.payments.push({date:val('pm-date')||TODAY, amount:amt, method:val('pm-method'), ref:val('pm-ref')||'—'}); const nt = calc.inv(i);
  log(`Payment received <b>${fmtR(amt,true)}</b> on ${i.id} — now ${nt.status}`, i.clientId, 'invoices-'+i.id, 'payment'); notify('payment', `Payment received ${fmtR(amt,true)} from ${get.client(i.clientId).name}`, 'invoices-'+i.id);
  const p = i.projectId && get.project(i.projectId);
  closeTop(); commit(`Payment recorded — ${i.id} is ${nt.status.toLowerCase()}`);
  if(p && p.status==='Awaiting authorization' && nt.status==='Paid') setTimeout(()=>toast(`${p.name} can now be authorised to start`, 'info'), 600);
};
A.recordPaymentPick = () => { closePop(); const open = DB.invoices.filter(i=>calc.inv(i).outstanding>0); modal({title:'Record payment', size:'sm', body: open.length?`<div class="list" style="border:1px solid var(--line);border-radius:10px;overflow:hidden">${open.map(i=>{ const t=calc.inv(i); return `<div class="li" data-a="recordPaymentGo" data-id="${i.id}"><div class="grow"><div class="t">${i.id} · ${esc(get.client(i.clientId).name)}</div><div class="s">${esc(i.desc)}</div></div><div class="col" style="gap:2px;align-items:flex-end"><b class="num small">${fmtR(t.outstanding,true)}</b>${badge(t.status)}</div></div>`; }).join('')}</div>`:empty('check-circle-2','Nothing outstanding','All issued invoices are paid.')}); };
A.recordPaymentGo = d => { closeTop(); A.recordPayment(d); };
A.newInvoice = d => { d = d||{}; closePop(); modal({title:'New invoice', body:`<div class="form-grid">${field('Client *',`<select class="sel" id="ni-client">${clientOpts(d.client,'Select client')}</select>`)}${field('Related quote',`<select class="sel" id="ni-quote">${opts(DB.quotes.filter(q=>q.status==='Accepted').map(q=>[q.id,q.id+' · '+q.title]), d.quote||'', {blank:'None'})}</select>`)}${field('Project',`<select class="sel" id="ni-proj">${opts(DB.projects.map(p=>[p.id,p.id+' · '+p.name]), d.project||'', {blank:'None'})}</select>`)}${field('Payment terms (days)',`<input class="inp" type="number" id="ni-terms" value="14">`)}${field('Description *',`<input class="inp" id="ni-desc" value="${esc(d.desc||'')}">`,'span2')}${field('Amount ex VAT (R) *',`<input class="inp num" type="number" id="ni-sub" value="${d.sub||''}">`)}${field('Save as',`<select class="sel" id="ni-flag">${opts([['draft','Draft'],['issued','Issued']],'draft')}</select>`)}</div><p class="muted xs mt-12">VAT is added automatically. Use <b>Send invoice</b> on the invoice to email it to the client.</p>`, foot:`<button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn pri" data-a="saveInvoice">${ic('check',14)}Create invoice</button>`}); };
A.saveInvoice = () => { if(!requireFields([['ni-client','Client'],['ni-desc','Description'],['ni-sub','Amount']])) return; const sub=+val('ni-sub'); if(!(sub>0)) return toast('Amount must be greater than zero','err');
  const i = {id:nextId('INV-',DB.invoices), clientId:val('ni-client'), quoteId:val('ni-quote')||null, projectId:val('ni-proj')||null, desc:val('ni-desc'), issued:TODAY, due:addDays(TODAY,+val('ni-terms')||14), subtotal:sub, vat:(DB.settings.workflow.vat??15)/100, payments:[], flag:val('ni-flag')==='draft'?'draft':null};
  DB.invoices.push(i); const c=get.client(i.clientId); if(['Accepted'].includes(c.status) && !i.flag) c.status='Payment pending';
  log(`${i.flag?'Drafted':'Issued'} invoice <b>${i.id}</b> for ${fmtR(sub*(1+(DB.settings.workflow.vat??15)/100),true)}`, i.clientId, 'invoices-'+i.id, 'invoice'); closeTop(); save(); go('invoices-'+i.id); toast(`${i.id} created`); };

/* ===================== PROJECTS ===================== */
function projRows(){ const f=UI.f.proj||'', cat=UI.f.projCat||'', pm=UI.f.projPm||'', q=(UI.q.proj||'').toLowerCase();
  return DB.projects.filter(p=>(!f || p.status===f) && (!cat || p.category===cat) && (!pm || p.pm===pm) && (!q || [p.name,p.id,get.client(p.clientId).name].join(' ').toLowerCase().includes(q))); }
const curStage = p => (p.workstreams.find(w=>w.status!=='Done')||{name:'Complete'}).name;
Views.projects = () => {
  const view = uv('pview','board'); const rows = projRows();
  const act = DB.projects.filter(p=>!['Completed','On hold'].includes(p.status));
  const kp = [
    {l:'Active projects', v:act.length, d:`${DB.projects.length} total`},
    {l:'Contract value (active)', v:fmtRk(sum(act,p=>p.budget)), d:'Ex VAT'},
    {l:'Average progress', v:Math.round(sum(act,p=>calc.progress(p))/Math.max(1,act.length))+'%', d:'Across active projects'},
    {l:'At risk / blocked', v:act.filter(p=>p.risk==='High'||p.status==='Blocked').length, d:act.filter(p=>p.status==='Blocked').map(p=>p.name).join(', ')||'None blocked', tone:'down'},
    {l:'Due this month', v:act.filter(p=>p.target.startsWith(TODAY.slice(0,7))).length, d:'Target this month', tone:'warn'}
  ];
  const toolbar = `<div class="toolbar">${searchBox('proj','Search projects…')}<select class="sel sm" data-ch="filt" data-key="proj" aria-label="Status">${opts(STATUS.project, UI.f.proj, {blank:'All statuses'})}</select><select class="sel sm" data-ch="filt" data-key="projCat" aria-label="Project type">${opts(STATUS.categories, UI.f.projCat, {blank:'All project types'})}</select><select class="sel sm" data-ch="filt" data-key="projPm" aria-label="Project manager">${opts(uniq(DB.projects.map(p=>p.pm)).map(id=>[id,uname(id)]), UI.f.projPm, {blank:'All PMs'})}</select>${(UI.f.proj||UI.f.projCat||UI.f.projPm||UI.q.proj)?`<button class="btn ghost sm" data-a="clearProj">${ic('x',13)}Clear</button>`:''}<span class="spacer"></span><span class="muted small">${rows.length} projects</span></div>`;
  let body='';
  if(view==='board'){
    const cols = STATUS.project.filter(s=>rows.some(p=>p.status===s) || !['Ready to start','Handover'].includes(s));
    body = `<div class="kb">${cols.map(s=>{ const ps=rows.filter(p=>p.status===s); return `<div class="kc" data-drop="${esc(s)}" data-kind="project"><div class="kc-h">${badge(s,null,'nodot')}<span class="ct">${ps.length}</span><span class="sum">${ps.length?fmtRk(sum(ps,p=>p.budget)):''}</span></div><div class="kc-b">${ps.map(p=>{ const c=get.client(p.clientId); const pr=calc.progress(p); return `<div class="kcard" draggable="true" data-drag="${p.id}" data-kind="project" data-go="project-${p.id}"><div class="row between"><span class="row" style="gap:6px"><span style="color:${CAT_COLOR[p.category]}">${ic(CAT_ICON[p.category],13)}</span><span class="mono xs muted">${p.id}</span></span>${p.risk==='High'?`<span class="b red nodot" style="height:18px">High risk</span>`:prio(p.priority)}</div><div class="kcard-t">${esc(p.name)}</div><div class="muted xs" style="margin:-3px 0 8px">${esc(c.name)}</div>${prog(pr, p.status==='Blocked'?'red':'')}<div class="kcard-m mt-8">${avs([p.pm].concat(p.team.filter(t=>t!==p.pm)),4)}<span class="${until(p.target)<0&&p.status!=='Completed'?'down':''}">${ic('calendar',11)} ${fmtDs(p.target)}</span></div></div>`; }).join('') || '<div class="kc-empty">No projects</div>'}</div></div>`; }).join('')}</div>`;
  }
  if(view==='table') body = card(null, table({key:'proj', rows, go:p=>'project-'+p.id, cols:[
    {k:'id',l:'ID',r:p=>`<span class="mono">${p.id}</span>`},{k:'name',l:'Project',r:p=>`<div class="cell-t">${esc(p.name)}</div><div class="cell-s">${esc(get.client(p.clientId).name)}</div>`},{k:'category',l:'Category',r:p=>catTag(p.category)},{k:'pm',l:'Project lead',r:p=>who(p.pm),sv:p=>uname(p.pm)},{k:'team',l:'Team',r:p=>avs(p.team,4),sort:false},{k:'start',l:'Start',r:p=>fmtD(p.start)},{k:'target',l:'Target',r:p=>`<span class="${until(p.target)<0&&p.status!=='Completed'?'down':''}">${fmtD(p.target)}</span>`},{k:'budget',l:'Budget',cls:'r',r:p=>`<span class="num">${fmtR(p.budget)}</span>`},{k:'stage',l:'Current stage',r:p=>esc(curStage(p)),sv:curStage},{k:'prog',l:'Progress',r:p=>prog(calc.progress(p),p.status==='Blocked'?'red':''),sv:p=>calc.progress(p)},{k:'priority',l:'Priority',r:p=>prio(p.priority),sv:p=>STATUS.priority.indexOf(p.priority)},{k:'pay',l:'Payment',r:p=>{const s=calc.payStatus(p); return badge(s.t,s.tone);},sv:p=>calc.payStatus(p).t},{k:'risk',l:'Risk',r:p=>badge(p.risk)},{k:'status',l:'Status',r:p=>badge(p.status),sv:p=>STATUS.project.indexOf(p.status)}
  ]}), {flush:true});
  if(view==='timeline') body = gantt(rows.filter(p=>p.status!=='Completed').map(p=>({id:p.id, label:p.name, sub:get.client(p.clientId).name, start:p.start, end:p.target, pr:calc.progress(p), color:CAT_COLOR[p.category], go:'project-'+p.id, status:p.status})));
  if(view==='calendar') body = calendar(rows);
  if(view==='workload') body = workloadMatrix(rows.filter(p=>!['Completed'].includes(p.status)));
  const html = `<div class="page full">${pageHead('Projects', 'Every engagement from authorisation to handover — by status, timeline and people.', `<button class="btn pri" data-a="newProject">${ic('plus',14)}New project</button>`)}
    <div class="kpis" style="grid-template-columns:repeat(5,minmax(0,1fr));margin-bottom:16px">${kp.map(kpiCell).join('')}</div>
    <div class="row between wrap" style="margin-bottom:12px">${segc('pview',[['board','Board','kanban'],['table','Table','table'],['timeline','Timeline','gantt-chart'],['calendar','Calendar','calendar'],['workload','Workload','users']],view)}${view==='board'?'<span class="muted small">Drag cards between columns to update status</span>':''}</div>${toolbar}<div class="tabpane">${body}</div></div>`;
  return {html, crumbs:[['Projects']], title:'Projects'};
};
A.clearProj = () => { UI.f.proj=''; UI.f.projCat=''; UI.f.projPm=''; UI.q.proj=''; rerender(); };
function gantt(items){
  if(!items.length) return card(null, empty('gantt-chart','Nothing to show',''));
  const s0 = items.map(i=>i.start).sort()[0], e0 = items.map(i=>i.end).sort().slice(-1)[0];
  const start = s0.slice(0,8)+'01'; const endD = pd(e0); const end = iso(new Date(Date.UTC(endD.getUTCFullYear(), endD.getUTCMonth()+1, 1)));
  const span = days(start,end); const x = d => Math.max(0,Math.min(100, days(start,d)/span*100));
  const months=[]; let m = start; while(m<end){ months.push(m); const dd=pd(m); m = iso(new Date(Date.UTC(dd.getUTCFullYear(), dd.getUTCMonth()+1, 1))); }
  return `<div class="gantt"><div class="gt"><div class="gt-h"><div class="gt-n">Name</div><div class="gt-tr">${months.map(mm=>`<span class="gt-m" style="left:${x(mm)}%">${MON[+mm.slice(5,7)-1]} ${mm.slice(2,4)}</span>`).join('')}</div></div>
    ${items.map(it=>`<div class="gt-r"><div class="gt-n"><span style="width:8px;height:8px;border-radius:2px;background:${it.color};flex:none"></span><div style="min-width:0"><div class="trunc strong" style="font-size:12.5px">${esc(it.label)}</div>${it.sub?`<div class="muted xs trunc">${esc(it.sub)}</div>`:''}</div></div><div class="gt-tr">${months.map(mm=>`<span class="gt-m" style="left:${x(mm)}%;padding:0"></span>`).join('')}<div class="gt-bar" ${it.go?`data-go="${it.go}"`:''} ${it.act||''} style="left:${x(it.start)}%;width:${Math.max(1.5,x(it.end)-x(it.start))}%;background:${it.status==='Blocked'?'var(--red)':it.color}" data-tip="${esc(it.label+'\n'+fmtD(it.start)+' → '+fmtD(it.end)+'\n'+it.pr+'% complete · '+(it.status||''))}"><span class="pf" style="width:${it.pr}%"></span><span>${it.pr}%</span></div></div></div>`).join('')}
    <div class="gt-today" style="left:calc(260px + (100% - 260px) * ${x(TODAY)/100})"></div></div></div>`;
}
window.gantt = gantt;
function calendar(rows){
  const ym = uv('calM',TODAY.slice(0,7)); const [y,m] = ym.split('-').map(Number);
  const first = new Date(Date.UTC(y,m-1,1)); const startDow = (first.getUTCDay()+6)%7; const gridStart = addDays(iso(first), -startDow);
  const ev = [];
  rows.forEach(p=>{ ev.push({d:p.target, t:'Due: '+p.name, cls:until(p.target)<0&&p.status!=='Completed'?'red':'cyan', go:'project-'+p.id}); (p.milestones||[]).forEach(ms=>ev.push({d:ms.date, t:'◆ '+ms.name, cls:ms.done?'green':'blue', go:'project-'+p.id})); p.workstreams.filter(w=>w.status!=='Done').forEach(w=>ev.push({d:w.due, t:w.name+' · '+p.name.split(' ')[0], cls:w.status==='Blocked'?'red':'amber', go:'project-'+p.id})); });
  const prev = m===1?`${y-1}-12`:`${y}-${String(m-1).padStart(2,'0')}`, next = m===12?`${y+1}-01`:`${y}-${String(m+1).padStart(2,'0')}`;
  let cells=''; for(let i=0;i<42;i++){ const d = addDays(gridStart,i); const es = ev.filter(e=>e.d===d); cells += `<div class="cal-d ${d.slice(0,7)!==ym?'out':''} ${d===TODAY?'today':''}"><span class="dn">${+d.slice(8)}</span>${es.slice(0,3).map(e=>`<span class="cal-e ${e.cls}" data-go="${e.go}" data-tip="${esc(e.t)}">${esc(e.t)}</span>`).join('')}${es.length>3?`<span class="muted xs">+${es.length-3} more</span>`:''}</div>`; }
  return `<div class="row between" style="margin-bottom:10px"><div class="row"><button class="ib sm" data-a="seg" data-key="calM" data-v="${prev}" aria-label="Previous month">${ic('chevron-left',16)}</button><b style="font-size:14px;min-width:130px;text-align:center">${['January','February','March','April','May','June','July','August','September','October','November','December'][m-1]} ${y}</b><button class="ib sm" data-a="seg" data-key="calM" data-v="${next}" aria-label="Next month">${ic('chevron-right',16)}</button><button class="btn ghost xs" data-a="seg" data-key="calM" data-v="${TODAY.slice(0,7)}">Today</button></div><div class="legend"><span><i style="background:var(--accent)"></i>Project due</span><span><i style="background:var(--blue)"></i>Milestone</span><span><i style="background:var(--amber)"></i>Workstream deadline</span><span><i style="background:var(--red)"></i>Overdue / blocked</span></div></div><div class="tw"><div class="cal" style="min-width:760px">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="cal-h">${d}</div>`).join('')}${cells}</div></div>`;
}
function workloadMatrix(projs){
  const people = DB.users.filter(u=>projs.some(p=>p.team.includes(u.id)||p.pm===u.id||p.tech===u.id));
  return card(null, `<div class="tw"><table class="tbl"><thead><tr><th>Person</th>${projs.map(p=>`<th style="white-space:normal;min-width:110px;max-width:130px"><a href="#project-${p.id}">${esc(p.name)}</a><div class="muted xs" style="font-weight:400">${esc(get.client(p.clientId).name.split(' ')[0])}</div></th>`).join('')}<th>Utilisation</th></tr></thead><tbody>${people.map(u=>{ const l=calc.load(u); return `<tr><td>${who(u.id)}<div class="muted xs" style="margin-left:31px">${esc(u.role)}</div></td>${projs.map(p=>{ const role = p.pm===u.id?'PM':p.tech===u.id?'Tech lead':p.team.includes(u.id)?'Team':''; const n = DB.tasks.filter(t=>t.projectId===p.id && t.assignee===u.id && t.status!=='Done').length; return `<td>${role?`<span class="b ${role==='PM'?'blue':role==='Tech lead'?'cyan':'gray'} nodot">${role}</span>${n?` <span class="muted xs">${n} task${n>1?'s':''}</span>`:''}`:''}</td>`; }).join('')}<td style="min-width:150px">${prog(l.util, l.util>100?'red':l.util>90?'amber':'')}</td></tr>`; }).join('')}</tbody></table></div>`, {flush:true});
}

/* ---------- Project detail ---------- */
Views.project = id => {
  const p = get.project(id); if(!p) return {html:`<div class="page">${empty('search-x','Project not found','')}</div>`};
  const c = get.client(p.clientId); const tab = uv('ptab','overview'); const pr = calc.progress(p); const ps = calc.payStatus(p);
  const tasks = DB.tasks.filter(t=>t.projectId===p.id); const docs = DB.documents.filter(x=>x.projectId===p.id);
  const pc = projCost(p); const margin = p.budget - pc; const estCost = pr>=15 ? Math.round(pc / (pr/100)) : pc;
  const left = until(p.target);
  const kp = [
    {l:'Progress', v:pr+'%', d:`${p.workstreams.filter(w=>w.status==='Done').length} of ${p.workstreams.length} workstreams done`},
    {l:'Budget (ex VAT)', v:fmtR(p.budget), d:p.quoteId?'From '+p.quoteId:'Change request'},
    {l:'Cost to date', v:fmtR(pc), d:`${pct(pc,p.budget)}% of budget used`, tone:pct(pc,p.budget)>pr+10?'down':''},
    {l:'Budget remaining', v:fmtR(margin), d:`Forecast cost ${fmtRk(Math.min(estCost, p.budget*1.4))}`, tone:margin>0?'up':'down'},
    {l:'Target date', v:fmtDs(p.target), d:p.status==='Completed'?'Delivered':left<0?`${-left} days late`:`${left} days left`, tone:left<0&&p.status!=='Completed'?'down':left<14?'warn':''},
    {l:'Payment status', v:`<span style="font-size:15px">${badge(ps.t,ps.tone)}</span>`, d:`${DB.invoices.filter(i=>i.projectId===p.id).length} invoices`}
  ];
  const tabs=[['overview','Overview'],['workstreams','Workstreams',p.workstreams.length],['tasks','Tasks',tasks.length],['timeline','Timeline'],['team','Team',uniq([p.pm,p.tech,p.owner].concat(p.team)).length],['activity','Activity']];
  let body='';
  if(tab==='overview'){
    const roles = [['Project owner',p.owner,'Accountable for commercial outcome'],['Project manager',p.pm,'Plans, coordinates and reports'],['Technical lead',p.tech,'Owns architecture and code quality']];
    const owners = uniq(tasks.filter(t=>t.status!=='Done').map(t=>t.assignee));
    body = `<div class="grid g-21"><div class="stack">
      ${p.blocker||p.status==='Blocked'?`<div class="callout red">${ic('x-octagon',16)}<span><b>Blocked.</b> ${esc(p.blocker||'See blocked workstreams.')}</span></div>`:''}
      ${p.status==='Awaiting authorization'?`<div class="callout amber">${ic('lock',16)}<div class="grow"><b>Awaiting authorisation.</b> ${ps.t==='Deposit pending'?'The deposit invoice has not been paid. Work should not start until payment clears.':'Deposit received — ready to authorise.'}<div class="mt-8"><button class="btn sm ${ps.t==='Deposit pending'?'':'acc'}" data-a="authorise" data-id="${p.id}">${ic('unlock',13)}Authorise start</button></div></div></div>`:''}
      ${card('About this project', `<p style="line-height:1.6">${esc(p.description)}</p><div class="kv2 mt-16"><div><div class="k">Category</div><div class="v">${catTag(p.category)}</div></div><div><div class="k">Current stage</div><div class="v">${esc(curStage(p))}</div></div><div><div class="k">Priority</div><div class="v">${prio(p.priority)}</div></div><div><div class="k">Risk</div><div class="v">${badge(p.risk)}</div></div><div><div class="k">Start</div><div class="v">${fmtD(p.start)}</div></div><div><div class="k">Target completion</div><div class="v">${fmtD(p.target)}</div></div><div><div class="k">Client</div><div class="v"><a href="#client-${c.id}">${esc(c.name)}</a></div></div><div><div class="k">Quote</div><div class="v">${p.quoteId?`<a href="#quote-${p.quoteId}" class="mono">${p.quoteId}</a>`:'—'}</div></div></div>`)}
      ${card('Workstream status', chHBar({items:p.workstreams.map(w=>({label:w.name, value:{'Done':100,'In review':85,'In progress':45,'Blocked':30,'Not started':0}[w.status], color:w.status==='Done'?'var(--green)':w.status==='Blocked'?'var(--red)':w.status==='In review'?'var(--blue)':'var(--c1)', valueHtml:`<span class="small">${esc(w.status)}</span>`, tip:`${w.name}\n${w.status} · due ${fmtD(w.due)}\nOwner: ${uname(w.owner)}`, act:`data-a="editWs" data-p="${p.id}" data-w="${w.id}"`})), max:100}), {act:`<button class="btn ghost xs" data-a="seg" data-key="ptab" data-v="workstreams">Manage</button>`})}
      ${card('Budget vs cost', chHBar({items:[{label:'Contract value', value:p.budget, color:'var(--c2)'},{label:'Cost to date', value:pc, color:'var(--c5)'},{label:'Forecast cost', value:Math.min(estCost, p.budget*1.4), color:estCost>p.budget?'var(--red)':'var(--c4)', tip:'Cost to date ÷ progress'}]}), {hint:'Mock figures · ex VAT'})}
    </div><div class="stack">
      ${card('Responsibility', `<div class="col gap-12">${roles.map(([l,u,s])=>`<div class="row between" style="align-items:flex-start"><div><div class="small strong">${l}</div><div class="muted xs">${s}</div></div>${who(u)}</div>`).join('')}<div class="row between"><div><div class="small strong">Client contact</div><div class="muted xs">Approves deliverables</div></div><span>${esc(p.clientContact||c.contact)}</span></div><div class="row between"><div><div class="small strong">Task owners</div><div class="muted xs">One accountable owner per task</div></div>${owners.length?avs(owners,6):'<span class="muted small">—</span>'}</div></div>`)}
      ${card('Milestones', (p.milestones||[]).length?`<div class="tl">${p.milestones.map(m=>`<div class="tl-i"><span class="tl-ic" style="${m.done?'background:var(--green-soft);color:var(--green)':''}">${ic(m.done?'check':'flag',13)}</span><div class="tl-b"><div class="t">${esc(m.name)}</div><div class="s">${fmtD(m.date)} · ${m.done?'Done':dueTxt(m.date)}</div></div></div>`).join('')}</div>`:empty('flag','No milestones',''))}
      ${card('Open tasks', tasks.filter(t=>t.status!=='Done').length?`<div class="list">${tasks.filter(t=>t.status!=='Done').slice(0,6).map(t=>`<div class="li" data-a="openTask" data-id="${t.id}">${badge(t.status,null,'nodot')}<div class="grow"><div class="t">${esc(t.title)}</div><div class="s ${t.due<TODAY?'down':''}">${dueTxt(t.due)}</div></div>${av(t.assignee,'sm')}</div>`).join('')}</div>`:empty('check-square','No open tasks',''), {flush:true, act:`<button class="btn ghost xs" data-a="newTask" data-project="${p.id}">${ic('plus',12)}Task</button>`})}
    </div></div>`;
  }
  if(tab==='workstreams') body = card(null, `<div class="tw"><table class="tbl"><thead><tr><th>Workstream</th><th>Responsible</th><th>Reviewer</th><th>Status</th><th>Priority</th><th>Deadline</th><th>Dependencies</th><th>Deliverables</th><th>Notes</th></tr></thead><tbody>${p.workstreams.map(w=>`<tr data-a="editWs" data-p="${p.id}" data-w="${w.id}"><td><span class="cell-t">${esc(w.name)}</span></td><td>${who(w.owner)}</td><td>${who(w.reviewer)}</td><td><select class="sel sm" data-ch="wsStatus" data-p="${p.id}" data-w="${w.id}" aria-label="Status">${opts(STATUS.ws, w.status)}</select></td><td>${prio(w.priority)}</td><td class="${w.due<TODAY&&w.status!=='Done'?'down':''}">${fmtD(w.due)}</td><td>${w.deps.map(d=>`<span class="tag">${esc(d)}</span>`).join(' ')||'<span class="muted">—</span>'}</td><td>${w.deliverables.length?`<span class="tag">${ic('package',12)}${w.deliverables.length}</span>`:'<span class="muted">—</span>'}</td><td class="wrap muted small" style="min-width:200px">${esc(w.notes)}</td></tr>`).join('')}</tbody></table></div>`, {flush:true, act:`<button class="btn sm" data-a="addWs" data-p="${p.id}">${ic('plus',13)}Add workstream</button>`});
  if(tab==='tasks') body = `<div class="toolbar"><span class="muted small">Drag tasks between columns. Every task has exactly one accountable owner.</span><span class="spacer"></span><button class="btn sm" data-a="newTask" data-project="${p.id}">${ic('plus',13)}New task</button></div>` + taskBoard(tasks);
  if(tab==='timeline'){ let prev = p.start; body = gantt(p.workstreams.map(w=>{ const s = prev<w.due?prev:addDays(w.due,-5); prev = w.due; return {label:w.name, sub:uname(w.owner), start:s, end:w.due, pr:{'Done':100,'In review':85,'In progress':45,'Blocked':30,'Not started':0}[w.status], color:w.status==='Done'?'var(--green)':'var(--c1)', status:w.status, act:`data-a="editWs" data-p="${p.id}" data-w="${w.id}"`}; })); }
  if(tab==='team'){ const ids = uniq([p.owner,p.pm,p.tech].concat(p.team)); body = `<div class="grid g3">${ids.map(uid=>{ const u=get.user(uid); const r=[p.owner===uid&&'Project owner',p.pm===uid&&'Project manager',p.tech===uid&&'Technical lead',p.team.includes(uid)&&'Team member'].filter(Boolean); const ot=tasks.filter(t=>t.assignee===uid&&t.status!=='Done'); return `<div class="member" data-go="team-${uid}"><div class="row">${av(uid,'lg')}<div class="grow"><div class="strong">${esc(u.name)}</div><div class="muted small">${esc(u.role)}</div></div></div><div class="row wrap">${r.map(x=>`<span class="tag">${x}</span>`).join('')}</div><div class="row between small"><span class="muted">Open tasks on project</span><b>${ot.length}</b></div><div class="row between small"><span class="muted">Workstreams owned</span><b>${p.workstreams.filter(w=>w.owner===uid).length}</b></div></div>`; }).join('')}</div>`; }
  if(tab==='files') body = card(null, docTable(docs,'pdocs'), {flush:true, act:`<button class="btn sm" data-a="uploadDoc" data-client="${p.clientId}" data-project="${p.id}">${ic('upload',13)}Upload</button>`});
  if(tab==='activity'){ const acts = DB.activity.filter(a=>a.link==='project-'+p.id || (a.clientId===p.clientId)).slice(0,30); body = card(null, acts.length?acts.map(feedItem).join(''):empty('activity','No activity yet',''), {flush:true}); }
  const html = `<div class="page full">
    <div class="dh"><div class="dh-l"><span class="co-ic lg" style="color:${CAT_COLOR[p.category]}">${ic(CAT_ICON[p.category],20)}</span><div><h1>${esc(p.name)}</h1><div class="meta"><span class="mono">${p.id}</span><a href="#client-${c.id}">${esc(c.name)}</a>${catTag(p.category)}${prio(p.priority)}</div></div></div>
      <div class="ph-act"><select class="sel sm" data-ch="projStatus" data-id="${p.id}" aria-label="Project status">${opts(STATUS.project, p.status)}</select><button class="btn sm" data-a="newTask" data-project="${p.id}">${ic('plus',13)}Task</button><button class="btn sm" data-a="editProject" data-id="${p.id}">${ic('pen-line',13)}Edit</button>${(window.can&&can('delete_data'))?`<button class="ib sm" data-a="delProject" data-id="${p.id}" data-tip="Delete project" aria-label="Delete project">${ic('trash-2',15)}</button>`:''}</div></div>
    <div class="kpis" style="grid-template-columns:repeat(6,minmax(0,1fr));margin-bottom:16px">${kp.map(kpiCell).join('')}</div>
    ${tabsc('ptab', tabs, tab)}<div class="tabpane">${body}</div></div>`;
  return {html, crumbs:[['Projects','projects'],[p.name]], title:p.name};
};
A.projStatus = (v, d) => { const p=get.project(d.id); if(v==='In progress' && p.status==='Awaiting authorization' && calc.payStatus(p).t==='Deposit pending'){ rerender(); return A.authorise(d); } const from=p.status; p.status=v; if(v==='Completed') p.completed=TODAY; log(`${esc(p.name)}: ${esc(from)} → <b>${esc(v)}</b>`, p.clientId, 'project-'+p.id, v==='Blocked'?'blocked':'status'); if(v==='Blocked') notify('blocked', `${p.name} is blocked`, 'project-'+p.id); commit(`Status → ${v}`); };
A.authorise = d => { const p=get.project(d.id); const ps=calc.payStatus(p); confirmBox({title:'Authorise project start?', text: ps.t==='Deposit pending'?`<b>The deposit for ${esc(p.name)} has not been received.</b> Starting without payment is against policy. Only proceed if a director has approved an exception.`:`Deposit received. ${esc(p.name)} will move to Ready to start and the team will be notified.`, ok:ps.t==='Deposit pending'?'Authorise anyway':'Authorise', danger:ps.t==='Deposit pending', onOk:()=>{ p.status='Ready to start'; log(`Authorised start of <b>${esc(p.name)}</b>${ps.t==='Deposit pending'?' (policy exception)':''}`, p.clientId, 'project-'+p.id, 'status'); commit('Project authorised'); }}); };
A.wsStatus = (v, d) => { const p=get.project(d.p), w=p.workstreams.find(x=>x.id===d.w); w.status=v; log(`${esc(w.name)} → ${esc(v)} on ${esc(p.name)}`, p.clientId, 'project-'+p.id, v==='In review'?'review':'status'); if(v==='In review') notify('review', `Deliverable submitted for review: ${w.name} (${p.id})`, 'project-'+p.id); commit(`${w.name} → ${v}`); };
function wsForm(p, w){ return `<div class="form-grid">${field('Workstream name *',`<input class="inp" id="ws-name" value="${esc(w.name)}">`,'span2')}${field('Responsible person',`<select class="sel" id="ws-owner">${userOpts(w.owner)}</select>`)}${field('Reviewer',`<select class="sel" id="ws-rev">${userOpts(w.reviewer)}</select>`)}${field('Status',`<select class="sel" id="ws-status">${opts(STATUS.ws, w.status)}</select>`)}${field('Priority',`<select class="sel" id="ws-prio">${opts(STATUS.priority, w.priority)}</select>`)}${field('Deadline',`<input class="inp" type="date" id="ws-due" value="${w.due}">`)}${field('Dependencies',`<select class="sel" id="ws-deps" multiple size="4" style="height:auto;padding:4px">${p.workstreams.filter(x=>x.id!==w.id).map(x=>`<option ${w.deps.includes(x.name)?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`)}${field('Deliverables (one per line)',`<textarea class="ta" id="ws-del">${esc(w.deliverables.join('\n'))}</textarea>`,'span2')}${field('Notes',`<textarea class="ta" id="ws-notes">${esc(w.notes)}</textarea>`,'span2')}</div>`; }
A.editWs = d => { const p=get.project(d.p), w=p.workstreams.find(x=>x.id===d.w); modal({title:esc(w.name)+' · '+p.id, size:'lg', body:wsForm(p,w), foot:`${(window.can&&can('delete_data'))?`<button class="btn danger" style="margin-right:auto" data-a="delWs" data-p="${p.id}" data-w="${w.id}">${ic('trash-2',14)}Delete</button>`:''}<button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn pri" data-a="saveWs" data-p="${p.id}" data-w="${w.id}">Save workstream</button>`}); };
A.addWs = d => { const p=get.project(d.p); const w={id:p.id+'-W'+(p.workstreams.length+1)+'x'+(Date.now()%1000), name:'', owner:p.tech, reviewer:p.pm, status:'Not started', due:p.target, deliverables:[], notes:'', deps:[], priority:'Medium'}; modal({title:'Add workstream', size:'lg', body:wsForm(p,w), foot:`<button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn pri" data-a="saveWs" data-p="${p.id}" data-new="${w.id}">Add workstream</button>`}); };
A.saveWs = d => { if(!requireFields([['ws-name','Workstream name']])) return; const p=get.project(d.p); let w = d.w ? p.workstreams.find(x=>x.id===d.w) : {id:d.new}; Object.assign(w, {name:val('ws-name'), owner:val('ws-owner'), reviewer:val('ws-rev'), status:val('ws-status'), priority:val('ws-prio'), due:val('ws-due'), deps:Array.from(document.getElementById('ws-deps').selectedOptions).map(o=>o.value), deliverables:val('ws-del').split('\n').map(s=>s.trim()).filter(Boolean), notes:val('ws-notes')}); if(!d.w) p.workstreams.push(w); closeTop(); commit('Workstream saved'); };
function projectForm(p){ return `<div class="form-grid">${field('Client *',`<select class="sel" id="pf-client">${clientOpts(p.clientId,'Select client')}</select>`)}${field('Related quote',`<select class="sel" id="pf-quote">${opts(DB.quotes.filter(q=>q.status==='Accepted').map(q=>[q.id,q.id+' · '+q.title]), p.quoteId||'', {blank:'None'})}</select>`)}${field('Project name *',`<input class="inp" id="pf-name" value="${esc(p.name||'')}">`,'span2')}${field('Project type',`<input class="inp" id="pf-cat" list="ptype-list" value="${esc(p.category||'')}" placeholder="e.g. Website rebuild, Retainer, Training"><datalist id="ptype-list">${STATUS.categories.map(x=>`<option value="${esc(x)}">`).join('')}</datalist>`)}${field('Priority',`<select class="sel" id="pf-prio">${opts(STATUS.priority, p.priority||'Medium')}</select>`)}${field('Project owner',`<select class="sel" id="pf-owner">${userOpts(p.owner||DB.me)}</select>`)}${field('Project manager',`<select class="sel" id="pf-pm">${userOpts(p.pm||DB.me)}</select>`)}${field('Technical lead',`<select class="sel" id="pf-tech">${userOpts(p.tech||DB.me)}</select>`)}${field('Budget ex VAT (R)',`<input class="inp num" type="number" id="pf-budget" value="${p.budget||''}">`)}${field('Cost to date — labour, contractors (R)',`<input class="inp num" type="number" id="pf-cost" value="${p.cost||''}">`)}${field('Start date',`<input class="inp" type="date" id="pf-start" value="${p.start||addDays(TODAY,7)}">`)}${field('Target completion',`<input class="inp" type="date" id="pf-target" value="${p.target||addDays(TODAY,70)}">`)}${field('Team members',`<div class="row wrap" style="gap:6px 14px;max-height:120px;overflow:auto;border:1px solid var(--line);border-radius:7px;padding:8px">${DB.users.map(u=>`<label class="chk small"><input type="checkbox" class="pf-team" value="${u.id}" ${(p.team||[]).includes(u.id)?'checked':''}>${esc(u.name)}</label>`).join('')}</div>`,'span2')}${field('Description',`<textarea class="ta" id="pf-desc">${esc(p.description||'')}</textarea>`,'span2')}${p.id?'':`${field('Start from one of your templates',`<select class="sel" id="pf-tpl" data-ch="pfTpl">${opts(DB.templates.map(t=>[t.id,t.name]),'',{blank:DB.templates.length?'No template — write the stages below':'No templates yet (create them in Administration)'})}</select>`,'span2')}${field('Scope / stages for this project (one per line)',`<textarea class="ta" id="pf-ws" style="min-height:120px" placeholder="e.g.&#10;Requirements&#10;Design&#10;Build&#10;Client sign-off">${esc((p.stages||[]).join('\n'))}</textarea>`,'span2')}<label class="chk small span2"><input type="checkbox" id="pf-savetpl">Save these stages as a reusable template</label>`}</div>`; }
A.newProject = d => { d=d||{}; closePop(); const q = d.quote && get.quote(d.quote); const p = q ? {clientId:q.clientId, quoteId:q.id, name:q.title, category:q.type||'', budget:calc.quote(q).sub, description:q.description, stages:(q.scope||[]).slice()} : {clientId:d.client||''};
  modal({title:'New project', size:'lg', body:projectForm(p)+`<div class="callout mt-12">${ic('layers',15)}<span>Each line in <b>Scope / stages</b> becomes a workstream you can assign and track. Leave it empty and add workstreams later. ${DB.settings.workflow.depositRequired?'New projects start as <b>Awaiting authorization</b> until the deposit is paid.':''}</span></div>`, foot:`<button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn pri" data-a="saveProject">${ic('check',14)}Create project</button>`}); };
A.pfTpl = v => { const t = DB.templates.find(x=>x.id===v); const ta = document.getElementById('pf-ws'); if(t && ta){ ta.value = t.ws.join('\n'); const c=document.getElementById('pf-cat'); if(c && !c.value) c.value = t.category||''; } };
A.saveProject = () => { if(!requireFields([['pf-client','Client'],['pf-name','Project name']])) return; const cat=val('pf-cat'); const stages = val('pf-ws').split('\n').map(x=>x.trim()).filter(Boolean); const tpl = {ws:stages}; const id = nextId('P-',DB.projects); const start=val('pf-start'), target=val('pf-target'); const n = Math.max(1,tpl.ws.length); const span = Math.max(n, days(start,target));
  if(cat && !(DB.settings.projectTypes||[]).includes(cat)) (DB.settings.projectTypes=DB.settings.projectTypes||[]).push(cat);
  if(val('pf-savetpl') && stages.length) DB.templates.push({id:'TPL-'+Date.now().toString(36), name:val('pf-name')+' stages', category:cat, ws:stages.slice(), weeks:Math.max(1,Math.round(days(start,target)/7))});
  const p = {id, clientId:val('pf-client'), name:val('pf-name'), category:cat, owner:val('pf-owner'), pm:val('pf-pm'), tech:val('pf-tech'), team:$$('.pf-team').filter(x=>x.checked).map(x=>x.value), start, target, budget:+val('pf-budget')||0, cost:+val('pf-cost')||0, status:DB.settings.workflow.depositRequired?'Awaiting authorization':'Planning', priority:val('pf-prio'), risk:'Low', quoteId:val('pf-quote')||null, description:val('pf-desc'), clientContact:null, milestones:[{name:'Kick-off',date:start},{name:'Go-live',date:target}], workstreams:tpl.ws.map((w,i)=>({id:id+'-W'+(i+1), name:w, owner:val('pf-tech'), reviewer:val('pf-pm'), status:'Not started', due:addDays(start, Math.round(span*(i+1)/n)), deliverables:[], notes:'', deps:i?[tpl.ws[i-1]]:[], priority:'Medium'}))};
  if(!p.team.length) p.team=[p.tech]; DB.projects.push(p); const q=p.quoteId&&get.quote(p.quoteId); if(q) q.projectId=p.id;
  log(`Created project <b>${esc(p.name)}</b>`, p.clientId, 'project-'+p.id, 'project'); closeTop(); save(); go('project-'+p.id); toast(`${p.id} created${p.workstreams.length?` with ${p.workstreams.length} workstreams`:''}`); };
A.editProject = d => { const p=get.project(d.id); modal({title:'Edit '+p.id, size:'lg', body:projectForm(p), foot:`<button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn pri" data-a="updateProject" data-id="${p.id}">Save</button>`}); };
A.updateProject = d => { if(!requireFields([['pf-name','Project name']])) return; const p=get.project(d.id); const cat=val('pf-cat'); if(cat && !(DB.settings.projectTypes||[]).includes(cat)) (DB.settings.projectTypes=DB.settings.projectTypes||[]).push(cat); Object.assign(p,{clientId:val('pf-client'), quoteId:val('pf-quote')||null, name:val('pf-name'), category:val('pf-cat'), priority:val('pf-prio'), owner:val('pf-owner'), pm:val('pf-pm'), tech:val('pf-tech'), budget:+val('pf-budget')||0, cost:+val('pf-cost')||0, start:val('pf-start'), target:val('pf-target'), team:$$('.pf-team').filter(x=>x.checked).map(x=>x.value), description:val('pf-desc')}); closeTop(); commit('Project updated'); };

/* ===================== TASKS ===================== */
function taskCard(t){
  const p = get.project(t.projectId); const c = t.clientId ? get.client(t.clientId) : null; const od = t.status!=='Done' && t.due && t.due<TODAY;
  const blockedBy = t.deps.map(get.task).filter(x=>x && x.status!=='Done');
  return `<div class="kcard ${UI.lastDrop===t.id?'dropped':''}" draggable="true" data-drag="${t.id}" data-kind="task" data-a="openTask" data-id="${t.id}"><div class="row between"><span class="mono xs muted">${t.id}</span>${prio(t.priority)}</div><div class="kcard-t">${esc(t.title)}</div><div class="muted xs trunc" style="margin:-2px 0 8px">${p?esc(p.name)+' · '+esc(t.workstream):c?esc(c.name)+' · '+esc(t.workstream):esc(t.workstream)}</div>${blockedBy.length?`<div class="xs down" style="margin-bottom:6px">${ic('link',11)} Waiting on ${blockedBy.map(b=>b.id).join(', ')}</div>`:''}<div class="kcard-m"><span class="row" style="gap:8px"><span class="${od?'down':''}">${ic('calendar',11)} ${dueTxt(t.due)}</span>${t.comments.length?`<span>${ic('message-square',11)} ${t.comments.length}</span>`:''}${t.attachments.length?`<span>${ic('paperclip',11)} ${t.attachments.length}</span>`:''}</span>${t.assignee?av(t.assignee,'sm'):`<button class="btn acc xs" data-a="claimTask" data-id="${t.id}">${ic('hand',11)}Claim</button>`}</div>${!t.assignee?`<div class="xs" style="margin-top:6px;color:var(--accent-2)">${ic('users',11)} Open to ${esc(t.pool||'anyone')}</div>`:''}</div>`;
}
function taskBoard(tasks){ return `<div class="kb">${STATUS.task.map(s=>{ const ts=tasks.filter(t=>t.status===s); return `<div class="kc" data-drop="${s}" data-kind="task"><div class="kc-h">${badge(s,null,'nodot')}<span class="ct">${ts.length}</span>${s!=='Done'?`<button class="ib sm" style="margin-left:auto;width:22px;height:22px" data-a="newTask" data-status="${s}" aria-label="Add task to ${s}">${ic('plus',13)}</button>`:''}</div><div class="kc-b">${ts.sort((a,b)=>STATUS.priority.indexOf(a.priority)-STATUS.priority.indexOf(b.priority)||(a.due||'').localeCompare(b.due||'')).map(taskCard).join('') || '<div class="kc-empty">Drop tasks here</div>'}</div></div>`; }).join('')}</div>`; }
window.taskBoard = taskBoard;
function taskRows(){ const q=(UI.q.tasks||'').toLowerCase(), pf=UI.f.taskP||'', af=UI.f.taskA||'', pr=UI.f.taskPr||'', qf=UI.f.taskq||'';
  return DB.tasks.filter(t=>(!q || [t.title,t.id,t.workstream,t.description].join(' ').toLowerCase().includes(q)) && (!pf || (pf==='__crm' ? !t.projectId : t.projectId===pf)) && (!af || t.assignee===af) && (!pr || t.priority===pr) && (!qf || (qf==='overdue' ? (t.status!=='Done'&&t.due<TODAY) : qf==='mine' ? t.assignee===DB.me||t.reviewer===DB.me : qf==='pool' ? (!t.assignee && t.status!=='Done') : qf==='review' ? t.status==='In review' : qf==='blocked' ? t.status==='Blocked' : true))); }
Views.tasks = id => {
  const view = uv('tview','board'); const rows = taskRows(); const qf = UI.f.taskq||'';
  const open = DB.tasks.filter(t=>t.status!=='Done');
  const quick = [['','All tasks',DB.tasks.length],['pool','Up for grabs',DB.tasks.filter(t=>!t.assignee&&t.status!=='Done').length],['mine','Mine (owner or reviewer)',DB.tasks.filter(t=>t.assignee===DB.me||t.reviewer===DB.me).length],['overdue','Overdue',open.filter(t=>t.due<TODAY).length],['review','In review',DB.tasks.filter(t=>t.status==='In review').length],['blocked','Blocked',DB.tasks.filter(t=>t.status==='Blocked').length]];
  const toolbar = `<div class="toolbar">${searchBox('tasks','Search tasks…')}<select class="sel sm" data-ch="filt" data-key="taskP" aria-label="Project">${opts([['__crm','Client follow-ups (no project)']].concat(DB.projects.filter(p=>p.status!=='Completed').map(p=>[p.id,p.name])), UI.f.taskP, {blank:'All projects'})}</select><select class="sel sm" data-ch="filt" data-key="taskA" aria-label="Owner">${userOpts(UI.f.taskA,'All owners')}</select><select class="sel sm" data-ch="filt" data-key="taskPr" aria-label="Priority">${opts(STATUS.priority, UI.f.taskPr, {blank:'Any priority'})}</select>${(UI.f.taskP||UI.f.taskA||UI.f.taskPr||UI.q.tasks||qf)?`<button class="btn ghost sm" data-a="clearTasks">${ic('x',13)}Clear</button>`:''}<span class="spacer"></span><span class="muted small">${rows.length} tasks</span></div>`;
  let body = view==='board' ? taskBoard(rows) : card(null, table({key:'tasks', rows, act:t=>`data-a="openTask" data-id="${t.id}"`, cols:[
    {k:'id',l:'ID',r:t=>`<span class="mono">${t.id}</span>`},{k:'title',l:'Task',r:t=>`<span class="cell-t">${esc(t.title)}</span>`},{k:'projectId',l:'Project · workstream',r:t=>{ const p=get.project(t.projectId); return `<div>${p?esc(p.name):'<span class="muted">Client follow-up</span>'}</div><div class="cell-s">${esc(t.workstream)}</div>`; },sv:t=>(get.project(t.projectId)||{name:'~'}).name},{k:'assignee',l:'Owner',r:t=>who(t.assignee),sv:t=>uname(t.assignee)},{k:'reviewer',l:'Reviewer',r:t=>who(t.reviewer),sv:t=>(get.user(t.reviewer)||{name:''}).name},{k:'priority',l:'Priority',r:t=>prio(t.priority),sv:t=>STATUS.priority.indexOf(t.priority)},{k:'status',l:'Status',r:t=>badge(t.status),sv:t=>STATUS.task.indexOf(t.status)},{k:'start',l:'Start',r:t=>fmtDs(t.start)},{k:'due',l:'Due',r:t=>`<span class="${t.status!=='Done'&&t.due<TODAY?'down':''}">${dueTxt(t.due)}</span>`},{k:'deps',l:'Depends on',r:t=>t.deps.map(x=>`<span class="tag mono">${x}</span>`).join(' ')||'<span class="muted">—</span>',sort:false}
  ]}), {flush:true});
  const html = `<div class="page full">${pageHead('Tasks', 'Workstream tasks and client follow-ups. One accountable owner per task; reviewers approve.', `<button class="btn pri" data-a="newTask">${ic('plus',14)}New task</button>`)}
    <div class="row between wrap" style="margin-bottom:12px"><div class="row wrap">${quick.map(([v,l,n])=>`<button class="fchip ${qf===v?'on':''}" data-a="fchip" data-key="taskq" data-v="${v}">${l}<span class="ct">${n}</span></button>`).join('')}</div>${segc('tview',[['board','Board','kanban'],['list','List','list']],view)}</div>${toolbar}<div class="tabpane">${body}</div></div>`;
  if(id && get.task(id)) after(()=>{ if(!STACK.length) A.openTask({id}); });
  return {html, crumbs:[['Tasks','tasks']].concat(id?[[id]]:[]), title:'Tasks'};
};
A.clearTasks = () => { UI.f.taskP=''; UI.f.taskA=''; UI.f.taskPr=''; UI.q.tasks=''; UI.f.taskq=''; rerender(); };
A.openTask = d => {
  drawer({title:()=>{ const t=get.task(d.id); return `<span class="mono muted" style="font-weight:500">${t.id}</span> ${esc(t.title)}`; }, render:()=>{
    const t = get.task(d.id); const p = get.project(t.projectId); const c = t.clientId?get.client(t.clientId):p?get.client(p.clientId):null;
    return `<div class="col gap-16">
      <div class="row wrap">${!t.assignee&&t.status!=='Done'?`<button class="btn pri sm" data-a="claimTask" data-id="${t.id}">${ic('hand',13)}Claim this task</button>`:''}${t.status!=='Done'?`<button class="btn acc sm" data-a="taskDone" data-id="${t.id}">${ic('check',13)}Mark complete</button>`:`<button class="btn sm" data-a="taskReopen" data-id="${t.id}">${ic('rotate-ccw',13)}Reopen</button>`}${t.status!=='In review'&&t.status!=='Done'?`<button class="btn sm" data-a="taskReview" data-id="${t.id}">${ic('eye',13)}Submit for review</button>`:''}<button class="btn sm" data-a="newReminder" data-kind="task" data-ref="${t.id}" data-client="${c?c.id:''}">${ic('alarm-clock',13)}Reminder</button>${(window.can&&can('delete_data'))?`<button class="btn sm danger" data-a="delTask" data-id="${t.id}">${ic('trash-2',13)}Delete</button>`:''}</div>${!t.assignee?`<div class="callout cyan">${ic('users',15)}<span>Unclaimed — open to <b>${esc(t.pool||'anyone')}</b>. The first person to claim it becomes its owner${t.created?' · waiting since '+fmtDT(t.created):''}.</span></div>`:t.claimedAt?`<p class="muted xs">Claimed by ${esc(uname(t.assignee))} ${fmtDT(t.claimedAt)}</p>`:''}
      <div class="form-grid">${field('Status',`<select class="sel" data-ch="taskField" data-id="${t.id}" data-k="status">${opts(STATUS.task,t.status)}</select>`)}${field('Priority',`<select class="sel" data-ch="taskField" data-id="${t.id}" data-k="priority">${opts(STATUS.priority,t.priority)}</select>`)}${field('Accountable owner',`<select class="sel" data-ch="taskField" data-id="${t.id}" data-k="assignee">${userOpts(t.assignee, 'Unassigned — back to the pool')}</select>`)}${field('Reviewer',`<select class="sel" data-ch="taskField" data-id="${t.id}" data-k="reviewer">${userOpts(t.reviewer)}</select>`)}${field('Start date',`<input class="inp" type="date" value="${t.start||''}" data-ch="taskField" data-id="${t.id}" data-k="start">`)}${field('Due date',`<input class="inp" type="date" value="${t.due||''}" data-ch="taskField" data-id="${t.id}" data-k="due">`)}</div>
      <dl class="kv"><dt>Project</dt><dd>${p?`<a href="#project-${p.id}">${esc(p.name)}</a>`:'Client follow-up (no project)'}</dd><dt>Workstream</dt><dd>${esc(t.workstream)}</dd><dt>Client</dt><dd>${c?`<a href="#client-${c.id}">${esc(c.name)}</a>`:'—'}</dd><dt>Estimate</dt><dd>${t.est||'—'} hours</dd></dl>
      ${field('Description',`<textarea class="ta" data-ch="taskField" data-id="${t.id}" data-k="description">${esc(t.description)}</textarea>`)}
      <div><div class="eyebrow" style="margin-bottom:6px">Dependencies</div>${t.deps.length?`<div class="col" style="gap:6px">${t.deps.map(x=>{ const dt=get.task(x); return dt?`<div class="row" style="gap:8px">${badge(dt.status)}<a data-a="openTask" data-id="${dt.id}" href="#" class="small">${dt.id} · ${esc(dt.title)}</a></div>`:''; }).join('')}</div>`:'<p class="muted small">No dependencies.</p>'}</div>
      <div><div class="row between" style="margin-bottom:6px"><span class="eyebrow">Attachments</span><button class="btn ghost xs" data-a="attachFile" data-id="${t.id}">${ic('paperclip',12)}Attach</button></div>${t.attachments.length?`<div class="row wrap">${t.attachments.map(a=>`<span class="tag">${ic('file',12)}${esc(a)}</span>`).join('')}</div>`:'<p class="muted small">No attachments.</p>'}</div>
      <div><div class="eyebrow" style="margin-bottom:8px">Comments</div><div class="col gap-12">${t.comments.map(cm=>`<div class="row" style="align-items:flex-start;gap:10px">${av(cm.by,'sm')}<div class="grow"><div class="small"><b>${esc(uname(cm.by))}</b> <span class="muted xs">${fmtDT(cm.at)}</span></div><div class="small sub" style="line-height:1.5">${esc(cm.text)}</div></div></div>`).join('')}<div class="row" style="align-items:flex-start">${av(DB.me,'sm')}<textarea class="ta" id="tc-${t.id}" style="min-height:56px" placeholder="Write a comment…"></textarea></div><div class="row" style="justify-content:flex-end"><button class="btn sm pri" data-a="taskComment" data-id="${t.id}">Comment</button></div></div></div>
    </div>`; }});
};
A.taskField = (v, d) => { const t=get.task(d.id); if(d.k==='assignee' && !v){ t.assignee=null; t.pool=t.pool||'Sales'; log(`${esc(t.title)} returned to the ${esc(t.pool)} pool`, (get.project(t.projectId)||{}).clientId||t.clientId, 'tasks-'+t.id, 'task'); if(window.notifyPool) notifyPool(t); return commit('Returned to the pool'); } const from=t[d.k]; t[d.k]=v; if(d.k==='assignee'){ t.pool=null; t.assignedBy=DB.me; t.claimedAt=nowStamp(); } if(['status','assignee'].includes(d.k)){ log(`${esc(t.title)}: ${d.k==='status'?esc(from)+' → <b>'+esc(v)+'</b>':'owner → <b>'+esc(uname(v))+'</b>'}`, (get.project(t.projectId)||{}).clientId||t.clientId, 'tasks-'+t.id, 'task'); if(d.k==='assignee' && v!==DB.me) notify('task', `${uname(DB.me)} assigned you "${t.title}"`, 'tasks-'+t.id, v); } commit(d.k==='description'?'Description saved':'Task updated'); };
A.taskDone = d => { const t=get.task(d.id); if(!t.assignee){ t.assignee=DB.me; t.pool=null; t.claimedAt=nowStamp(); } t.status='Done'; t.doneAt=nowStamp(); log(`Completed <b>${esc(t.title)}</b>`, (get.project(t.projectId)||{}).clientId||t.clientId, 'tasks-'+t.id, 'task'); commit('Task completed'); };
A.taskReopen = d => { get.task(d.id).status='To do'; commit('Task reopened'); };
A.taskReview = d => { const t=get.task(d.id); t.status='In review'; notify('review', `Review requested: ${t.title}`, 'tasks-'+t.id, t.reviewer||null); commit('Submitted to '+(get.user(t.reviewer)||{name:'reviewer'}).name.split(' ')[0]+' for review'); };
A.taskComment = d => { const v=val('tc-'+d.id); if(!v) return; get.task(d.id).comments.push({by:DB.me, at:nowStamp(), text:v}); commit('Comment added'); };
A.attachFile = d => modal({title:'Attach file', size:'sm', body:`<div class="callout amber" style="margin-bottom:12px">${ic('flask-conical',15)}<span>Demo: the file name is recorded but the file is not uploaded. Production storage will use Supabase Storage.</span></div>${field('File name',`<input class="inp" id="af-name" placeholder="e.g. design-review-notes.pdf">`)}`, foot:`<button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn pri" data-a="saveAttach" data-id="${d.id}">Attach</button>`});
A.saveAttach = d => { if(!requireFields([['af-name','File name']])) return; get.task(d.id).attachments.push(val('af-name')); closeTop(); commit('Attachment added'); };
A.newTask = d => { d=d||{}; closePop(); const p = d.project ? get.project(d.project) : null;
  modal({title:'New task', size:'lg', body:`<div class="form-grid">${field('Title *',`<input class="inp" id="nt-title" placeholder="What needs to be done?">`,'span2')}${field('Project',`<select class="sel" id="nt-proj" data-ch="ntProj">${opts(DB.projects.filter(x=>x.status!=='Completed').map(x=>[x.id,x.id+' · '+x.name]), p?p.id:'', {blank:'No project — client follow-up'})}</select>`)}${field('Workstream',`<select class="sel" id="nt-ws">${wsOpts(p)}</select>`)}${field('Client (for follow-ups)',`<select class="sel" id="nt-client">${clientOpts(d.client||(p?p.clientId:''),'—')}</select>`)}${field('Assign to *',`<select class="sel" id="nt-owner">${opts([['pool:Sales','Up for grabs — any Sales rep can claim'],['pool:Delivery','Up for grabs — any Delivery member can claim'],['pool:Finance','Up for grabs — Finance'],['pool:Anyone','Up for grabs — anyone']].concat(DB.users.map(u=>[u.id,u.name+' · '+(u.sysRole||'')])), d.owner||(p?p.tech:DB.me))}</select>`)}${field('Reviewer',`<select class="sel" id="nt-rev">${userOpts(p?p.pm:'', 'No reviewer')}</select>`)}${field('Priority',`<select class="sel" id="nt-prio">${opts(STATUS.priority,'Medium')}</select>`)}${field('Status',`<select class="sel" id="nt-status">${opts(STATUS.task, d.status||'To do')}</select>`)}${field('Start',`<input class="inp" type="date" id="nt-start" value="${TODAY}">`)}${field('Due *',`<input class="inp" type="date" id="nt-due" value="${addDays(TODAY,3)}">`)}${field('Estimate (hours)',`<input class="inp" type="number" id="nt-est" value="2">`)}${field('Description',`<textarea class="ta" id="nt-desc"></textarea>`,'span2')}</div>`, foot:`<button class="btn ghost" data-a="closeTop">Cancel</button><button class="btn pri" data-a="saveTask">${ic('check',14)}Create task</button>`}); };
function wsOpts(p){ return p ? opts(p.workstreams.map(w=>w.name), (p.workstreams.find(w=>w.status!=='Done')||{}).name) : opts(['Client follow-up','Finance','Internal'],'Client follow-up'); }
A.ntProj = v => { const p=get.project(v); const ws=document.getElementById('nt-ws'); if(ws) ws.innerHTML = wsOpts(p); if(p){ const c=document.getElementById('nt-client'); if(c) c.value=p.clientId; const o=document.getElementById('nt-owner'); if(o) o.value=p.tech; const r=document.getElementById('nt-rev'); if(r) r.value=p.pm; } };
A.saveTask = () => { if(!requireFields([['nt-title','Title'],['nt-owner','Accountable owner'],['nt-due','Due date']])) return;
  const own = val('nt-owner'); const isPool = own.startsWith('pool:');
  const t = {id:nextId('T-',DB.tasks), title:val('nt-title'), projectId:val('nt-proj'), workstream:val('nt-ws'), assignee:isPool?null:own, pool:isPool?own.slice(5):null, created:nowStamp(), assignedBy:isPool?null:DB.me, reviewer:val('nt-rev')||null, priority:val('nt-prio'), status:val('nt-status'), start:val('nt-start'), due:val('nt-due'), est:+val('nt-est')||0, description:val('nt-desc'), deps:[], attachments:[], comments:[], clientId:val('nt-client')||null};
  DB.tasks.push(t); if(!t.assignee){ if(window.notifyPool) notifyPool(t); } else if(t.assignee!==DB.me) notify('task', `${uname(DB.me)} assigned you "${t.title}"`, 'tasks-'+t.id, t.assignee); log(`Created task <b>${esc(t.title)}</b> ${t.assignee?'for '+esc(uname(t.assignee)):'in the '+esc(t.pool)+' pool'}`, (get.project(t.projectId)||{}).clientId||t.clientId, 'tasks-'+t.id, 'task'); closeTop(); commit(`${t.id} created`); };

/* ===================== TEAM ===================== */
Views.team = id => {
  const users = DB.users; const loads = users.map(u=>({u, l:calc.load(u)}));
  const dept = UI.f.dept||'';
  const rows = loads.filter(x=>!dept || x.u.dept===dept);
  const over = loads.filter(x=>x.l.util>100);
  const kp = [{l:'Team members', v:users.length, d:`${uniq(users.map(u=>u.dept)).length} departments`},{l:'Available', v:users.filter(u=>u.status==='Available').length, d:`${users.filter(u=>u.status==='On leave').length} on leave`},{l:'Over capacity', v:over.length, d:over.map(x=>x.u.name.split(' ')[0]).join(', ')||'Nobody', tone:over.length?'down':''},{l:'Open tasks', v:DB.tasks.filter(t=>t.status!=='Done').length, d:`${DB.tasks.filter(t=>t.status!=='Done'&&t.due<TODAY).length} overdue`, tone:'warn'},{l:'Average utilisation', v:Math.round(sum(loads,x=>x.l.util)/loads.length)+'%', d:'Allocated vs capacity'}];
  const html = `<div class="page full">${pageHead('Team', 'Who is working on what, how loaded they are, and who is accountable.', `<button class="btn" data-a="go" data-to="admin">${ic('user-plus',14)}Invite member</button>`)}
    <div class="kpis" style="grid-template-columns:repeat(5,minmax(0,1fr));margin-bottom:16px">${kp.map(kpiCell).join('')}</div>
    <div class="grid g-21">
      ${card('Workload by person', chHBar({items:loads.slice().sort((a,b)=>b.l.util-a.l.util).map(x=>({label:x.u.name, value:x.l.util, color:x.l.util>100?'var(--red)':x.l.util>90?'var(--amber)':x.u.status==='On leave'?'var(--fg-4)':'var(--c1)', marker:100, tip:`${x.u.name} · ${x.u.role}\n${x.u.alloc}h of ${x.u.capacity}h per week\n${x.l.open} open tasks · ${x.l.overdue} overdue`, go:'team-'+x.u.id})), fmt:v=>v+'%', max:125}), {hint:'Marker = 100% capacity'})}
      ${card('Responsibility model', `<div class="col gap-12 small">${[['Project owner','Accountable for the client relationship and commercial outcome.','briefcase'],['Project manager','Plans, coordinates, reports status and manages risks.','clipboard-list'],['Technical lead','Owns architecture, code quality and technical decisions.','cpu'],['Task owner','The one person accountable for completing a task.','user-check'],['Reviewer','Checks and approves work before it is marked done.','eye'],['Client contact','The client-side person who approves deliverables.','handshake']].map(([t,s,i])=>`<div class="row" style="align-items:flex-start;gap:10px"><span class="src manual">${ic(i,13)}</span><div><b>${t}</b><div class="muted">${s}</div></div></div>`).join('')}</div>`)}
    </div>
    <div class="row between wrap mt-16" style="margin-bottom:12px"><div class="row wrap">${[''].concat(uniq(users.map(u=>u.dept))).map(dp=>`<button class="fchip ${dept===dp?'on':''}" data-a="fchip" data-key="dept" data-v="${dp}">${dp||'All departments'}<span class="ct">${dp?users.filter(u=>u.dept===dp).length:users.length}</span></button>`).join('')}</div></div>
    <div class="grid g4">${rows.map(({u,l})=>`<div class="member" data-a="openMember" data-id="${u.id}"><div class="row">${av(u.id,'lg')}<div class="grow" style="min-width:0"><div class="strong trunc">${esc(u.name)}</div><div class="muted small trunc">${esc(u.role)}</div></div>${badge(u.status)}</div><div class="row between small"><span class="muted">${esc(u.dept)}</span><span class="muted">${l.projects} project${l.projects===1?'':'s'}</span></div><div class="stats"><div><b>${l.open}</b><span>Active</span></div><div><b>${l.done}</b><span>Completed</span></div><div><b class="${l.overdue?'down':''}">${l.overdue}</b><span>Overdue</span></div></div><div><div class="row between xs muted" style="margin-bottom:4px"><span>Workload</span><span>${u.alloc}h / ${u.capacity}h</span></div>${prog(l.util, l.util>100?'red':l.util>90?'amber':'')}</div></div>`).join('')}</div></div>`;
  if(id && get.user(id)) after(()=>{ if(!STACK.length) A.openMember({id}); });
  return {html, crumbs:[['Team','team']].concat(id&&get.user(id)?[[uname(id)]]:[]), title:'Team'};
};
A.openMember = d => drawer({title:()=>esc(uname(d.id)), render:()=>{
  const u=get.user(d.id), l=calc.load(u); const tasks = DB.tasks.filter(t=>t.assignee===u.id && t.status!=='Done'); const rev = DB.tasks.filter(t=>t.reviewer===u.id && t.status==='In review');
  const projs = DB.projects.filter(p=>p.status!=='Completed' && (p.team.includes(u.id)||p.pm===u.id||p.tech===u.id||p.owner===u.id));
  return `<div class="col gap-16"><div class="row">${av(u.id,'xl')}<div class="grow"><div class="strong" style="font-size:16px">${esc(u.name)}</div><div class="muted">${esc(u.role)} · ${esc(u.dept)}</div><div class="muted small mono">${esc(u.email)} · ${esc(u.phone)}</div></div></div>
    <div class="form-grid">${field('Availability',`<select class="sel" data-ch="memberStatus" data-id="${u.id}">${opts(['Available','Busy','On leave'],u.status)}</select>`)}${field('Allocated hours / week',`<input class="inp" type="number" value="${u.alloc}" data-ch="memberAlloc" data-id="${u.id}">`)}</div>
    <div class="kpis" style="grid-template-columns:repeat(4,1fr)">${kpiCell({l:'Utilisation',v:l.util+'%',tone:l.util>100?'down':''})}${kpiCell({l:'Open tasks',v:l.open})}${kpiCell({l:'Overdue',v:l.overdue,tone:l.overdue?'down':''})}${kpiCell({l:'Completed',v:l.done})}</div>
    ${l.util>100?`<div class="callout red">${ic('alert-triangle',15)}<span>${esc(u.name.split(' ')[0])} is allocated ${u.alloc}h against ${u.capacity}h capacity. Consider reassigning work.</span></div>`:''}
    ${card('Projects', projs.length?`<div class="list">${projs.map(p=>`<div class="li" data-go="project-${p.id}"><div class="grow"><div class="t">${esc(p.name)}</div><div class="s">${[p.owner===u.id&&'Owner',p.pm===u.id&&'Project manager',p.tech===u.id&&'Technical lead',p.team.includes(u.id)&&'Team'].filter(Boolean).join(' · ')}</div></div>${badge(p.status)}</div>`).join('')}</div>`:empty('folder','No active projects',''), {flush:true})}
    ${card('Accountable tasks', tasks.length?`<div class="list">${tasks.map(t=>`<div class="li" data-a="openTask" data-id="${t.id}">${badge(t.status,null,'nodot')}<div class="grow"><div class="t">${esc(t.title)}</div><div class="s ${t.due<TODAY?'down':''}">${dueTxt(t.due)}</div></div>${prio(t.priority)}</div>`).join('')}</div>`:empty('check-square','No open tasks',''), {flush:true})}
    ${rev.length?card('Waiting for their review', `<div class="list">${rev.map(t=>`<div class="li" data-a="openTask" data-id="${t.id}"><div class="grow"><div class="t">${esc(t.title)}</div><div class="s">Owner: ${esc(uname(t.assignee))}</div></div></div>`).join('')}</div>`, {flush:true}):''}</div>`; }});
A.memberStatus = (v,d) => { get.user(d.id).status=v; commit('Availability updated'); };
A.memberAlloc = (v,d) => { get.user(d.id).alloc=Math.max(0,+v||0); commit('Allocation updated'); };

})();
